        "question": "Discuss the major approaches to the study of Indian society. Compare the Indological, Field-View, and Historical approaches in\nterms of their assumptions, methods, and limitations. [6 Marks]",
        "answer": "Comprehensive review: Need for specific Indian sociology; (1) Indological approach (Ghurye, Sanskrit texts,\nreconstruction of classical institutions, elite textual bias); (2) Field-view/empirical approach (Srinivas, village\nstudies, participant observation, present-day relevance); (3) Historical approach (archives, temporal change,\nreliance on colonial documents); Comparative evaluation.",
        "explanation": "Step-by-Step Marking Scheme (2 Marks Indological + 2 Marks Field-View + 2 Marks Historical):\n• 1. Indological Approach [2 Marks]:\n- Assumptions: Indian society is a unique civilisational continuity rooted in Sanskritic classical traditions.\n- Methods: Study of Vedas, Shastras, Puranas, and Dharmashastras.\n- Limitations: Elite Brahminical, patriarchal, textual bias; neglects subaltern experiences and contemporary change.\n• 2. Field-View (Empirical) Approach [2 Marks]:\n- Assumptions: Social reality must be studied through direct observation of living people.\n- Methods: Village surveys, participant observation, interviews, statistical analysis of census data (Srinivas's Rampura\nstudies).\n- Strengths: Grounded in contemporary reality; captures change and diversity.\n• 3. Historical Approach [2 Marks]:\n- Assumptions: Present institutions can only be understood through their historical evolution.\n- Methods: Archival research, colonial records, comparative historical analysis.\n- Limitations: Dependence on official colonial documents that reflect the biases of rulers."
