        "question": "Analyse the concept of 'Sanskritization'. Explain its processes, forms, and consequences, and critically evaluate its limitations as\na theory of social change. [6 Marks]",
        "answer": "Comprehensive analysis: Definition and origin (M.N. Srinivas, 1952, study of Coorgs); Processes (adopting\nvegetarianism, teetotalism, Brahminical rituals, claiming varna status, dowry, sectarian membership); Forms\n(cultural, positional, varna mobility); Consequences (status mobility, upward aspiration); Limitations (no\nstructural change, reinforces hierarchy, patriarchal appropriation, decline in modern era).\nStep-by-Step Marking Scheme (1 Mark definition + 2 Marks processes/forms + 1.5 Marks consequences + 1.5 Marks critical\nlimitations):\n• 1. Definition [1 Mark]:\n- Sanskritization is the process by which a low caste or tribe adopts the customs, rituals, beliefs, ideology, and lifestyle of\na high (twice-born) caste to claim a higher position in the ritual hierarchy.\n• 2. Processes and Forms [2 Marks]:\n- Cultural adoption: vegetarianism, teetotalism, wearing the sacred thread, Sanskritic worship, child marriage/dowry.\n- Claims to higher varna status, migration to new regions, and adoption of a more prestigious caste name.\n• 3. Consequences [1.5 Marks]:\n- Provides a cultural avenue for upward mobility where economic and political avenues are closed.\n- Can produce changes in status without altering the structural hierarchy.\n• 4. Critical Limitations [1.5 Marks]:\n\n- Srinivas himself noted it produces positional change, not structural change.\n- It can entrench caste hierarchy and patriarchal customs rather than dismantle them, and its relevance has declined with\ndemocratic politics and economic liberalisation.",
