        "tag": "CBSE 2023 - 4/6 Marks",
        "question": "Examine the relationship between 'Caste' and 'Class' in contemporary Indian society. To what extent has economic\ndevelopment weakened caste identities? [6 Marks]",
        "answer": "Comprehensive examination: Theoretical distinction (caste: ritual/ascriptive; class: economic/achievement-\nbased); Interpenetration (caste-based occupational structure historically linked caste and class); Transformations\n(industrialisation, urbanisation, education, land reforms, affirmative action); Persistence (caste-based political\nmobilisation, endogamy, caste associations, Dalit capitalism); Analytical synthesis.\nStep-by-Step Marking Scheme (1.5 Marks theoretical distinction + 2 Marks historical interpenetration + 1.5 Marks forces\nweakening caste + 1 Mark persistence of caste):\n• 1. Theoretical Distinction [1.5 Marks]:\n- Caste is an ascriptive, ritual, hereditary system based on purity-pollution; class is an achievement-based economic\ncategory defined by ownership of the means of production.\n• 2. Historical Interpenetration [2 Marks]:\n- In traditional India, caste determined occupation, so caste and class largely coincided (jajmani system).\n- Landowning upper castes occupied both high ritual and high economic positions; service castes were economically\ndependent.\n• 3. Forces Weakening Caste [1.5 Marks]:\n- Industrialisation, urbanisation, modern education, land reforms, and constitutional equality have opened non-caste-\nbased occupational mobility.\n- Globalisation has created new class formations based on professional skill rather than caste.\n• 4. Persistence of Caste [1 Mark]:\n- Despite economic change, caste survives through endogamy, matrimonial alliances, caste associations, and caste-based\nelectoral politics.",
