        "question": "Evaluate the role of colonial ethnography and the census in shaping modern Indian identities. How did colonial knowledge\nproduction affect caste, tribe, and religious community identities? [6 Marks]",
        "answer": "Detailed evaluation: Colonial knowledge production as power (Bernard Cohn, Edward Said's Orientalism); (1)\nCensus: ranking and objectification of castes, fixing fluid identities, creating 'depressed classes'; (2) Ethnographic\nsurveys: codification of tribal categories and customary law; (3) Religious community enumeration: separate\nelectorates and Hindu-Muslim polarisation; Consequences: politicised identities and modern identity politics.\nStep-by-Step Marking Scheme (1.5 Marks colonial knowledge as power + 2 Marks census and caste objectification + 1.5\nMarks community enumeration + 1 Mark long-term consequences):\n• 1. Colonial Knowledge as Power [1.5 Marks]:\n- Drawing on Edward Said's 'Orientalism' and Bernard Cohn's work, colonial knowledge production classified, ranked, and\n'objectified' Indian society, transforming it into a governable entity.\n• 2. Census and Caste Objectification [2 Marks]:\n- The decennial census ranked castes in hierarchical lists (Risley's nasal index), fixing fluid and regionally varied identities\ninto rigid, permanent categories.\n- This hardened caste boundaries and created new caste consciousness and claims.\n• 3. Religious Community Enumeration [1.5 Marks]:\n- Enumeration of religious communities and separate electorates institutionalised communal identities, contributing to\nHindu-Muslim polarisation and partition.\n• 4. Long-Term Consequences [1 Mark]:\n- Colonial classifications provided the administrative scaffolding for modern identity politics, reservations, and\ncommunity-based mobilisation.",
