        "answer": "Comprehensive analysis: Theoretical definitions (Benedict Anderson's imagined community, Ernest Gellner,\nAnthony Smith's civic vs ethnic models); Indian nationalism: civic-territorial basis (Constitution, citizenship,\ninclusive secularism); cultural-ethnic strains (Hindutva, linguistic nationalism, religious majoritarianism); Anti-\ncolonial synthesis; Contemporary tensions (CAA, language politics); Evaluation.\nStep-by-Step Marking Scheme (1.5 Marks theoretical frameworks + 2 Marks civic-territorial basis of Indian nationalism +\n1.5 Marks cultural-ethnic strains + 1 Mark evaluation):\n• 1. Theoretical Frameworks [1.5 Marks]:\n- Benedict Anderson's 'imagined community'; Anthony Smith's distinction between civic (territorial, legal) and ethnic\n(descent, culture) nations.\n• 2. Civic-Territorial Basis of Indian Nationalism [2 Marks]:\n- Indian nationalism emerged from anti-colonial struggle and is grounded in constitutional citizenship, territory, and\ninclusive secularism.\n- The Constitution guarantees equal rights irrespective of religion, caste, language, or region.\n• 3. Cultural-Ethnic Strains [1.5 Marks]:\n- Competing visions invoke cultural homogenisation — linguistic chauvinism, religious majoritarianism, and ethnic\nassertions.\n• 4. Evaluation [1 Mark]:\n\n- Indian nationalism remains an ongoing negotiation between constitutional pluralism and majoritarian cultural claims.",
