        "answer": "Detailed examination: Village as the traditional unit of Indian society; (1) M.N. Srinivas: Rampura studies (The\nRemembered Village), concepts of dominant caste, Sanskritization, vertical solidarity; (2) S.C. Dube: Shamirpet,\nIndian Village as a 'little republic'; (3) Andre Beteille: Sripuram, Caste, Class and Power — critique of consensus\nmodel, rise of class; Changing nature: agrarian capitalism, migration, decline of jajmani, panchayati raj.\nStep-by-Step Marking Scheme (1.5 Marks significance of village studies + 1.5 Marks Srinivas + 1.5 Marks Dube and Beteille\n+ 1.5 Marks changing village):\n• 1. Significance of Village Studies [1.5 Marks]:\n- Over 70% of India's population historically lived in villages; village studies provided the empirical foundation for\nunderstanding caste, kinship, and agrarian relations.\n• 2. M.N. Srinivas [1.5 Marks]:\n- His Rampura study ('The Remembered Village') produced key concepts: dominant caste, Sanskritization, and\nvertical/inter-caste solidarity.\n• 3. S.C. Dube and Andre Beteille [1.5 Marks]:\n- Dube's Shamirpet study portrayed the village as a 'little republic' with integrated caste and factional politics.\n- Beteille's Sripuram study analysed the growing separation of caste, class, and power in agrarian society.\n• 4. Changing Nature of the Village [1.5 Marks]:\n- Decline of jajmani relations, rise of agrarian capitalism and market relations, out-migration, and the impact of\npanchayati raj decentralisation.",
