        "tag": "CBSE 2018 - 4/6 Marks",
        "question": "Examine the sociological significance of the concepts 'Sanskritization' and 'Westernisation' in understanding social change in\nIndia. Compare their scope, direction, and long-term implications. [6 Marks]",
        "answer": "Detailed comparative examination: Both coined by M.N. Srinivas; (1) Sanskritization: internal, vertical mobility,\nritual/ideological, conservative, caste-preserving; (2) Westernisation: external, horizontal, technological and\nvalue-based (humanitarianism, secularism, rationalism), modernising, egalitarian potential; Comparative table of\nscope, direction, agents, effects; Contemporary relevance.\nStep-by-Step Marking Scheme (1.5 Marks Sanskritization + 1.5 Marks Westernisation + 2 Marks comparison + 1 Mark\ncontemporary relevance):\n• 1. Sanskritization [1.5 Marks]:\n- An internal, endogenous process of upward mobility within the caste hierarchy through ritual emulation; essentially\nconservative as it accepts the caste order.\n• 2. Westernisation [1.5 Marks]:\n- An exogenous process involving adoption of Western technology, education, dress, humanitarianism, secularism, and\nrationalism; cuts across caste lines and is more egalitarian.\n• 3. Comparison [2 Marks]:\n- Sanskritization is vertical, ritual, and status-preserving; Westernisation is horizontal, material, and value-transforming.\n- Sanskritization is primarily rural and caste-bound; Westernisation is urban and class-based.\n• 4. Contemporary Relevance [1 Mark]:\n- Globalisation has accelerated westernisation while Sanskritization persists in politics and marriage patterns.",
