        "question": "\"The Indian Constitution provides the institutional foundation for managing social diversity.\" Evaluate this statement with\nreference to the provisions for Scheduled Castes, Scheduled Tribes, Other Backward Classes, minorities, and linguistic groups.\n[6 Marks]",
        "answer": "Critical evaluation: Constitutional architecture of diversity management; (1) Abolition of untouchability (Article\n17), equality (Articles 14-16), non-discrimination; (2) Reservations: SCs (Article 341, 15(4), 16(4), 330/332), STs\n(Article 342), OBCs (Article 15(4), 340; Mandal Commission 1990); (3) Linguistic rights (Eighth Schedule 22\nlanguages, three-language formula, Official Languages Act); (4) Minority rights (Articles 25-30: freedom of\nreligion, cultural and educational institutions); (5) Fifth and Sixth Schedules (tribal areas); Evaluation.\nStep-by-Step Marking Scheme (1.5 Marks equality provisions + 1.5 Marks reservations + 1.5 Marks linguistic rights + 1.5\nMarks minority and tribal provisions):\n• 1. Equality and Non-Discrimination [1.5 Marks]:\n- Article 17 abolishes untouchability; Articles 14, 15, and 16 guarantee equality before law and prohibit discrimination on\ngrounds of religion, race, caste, sex, or place of birth.\n• 2. Protective Discrimination [1.5 Marks]:\n- Articles 15(4) and 16(4) enable reservations for SCs (Article 341), STs (Article 342), and OBCs (Article 15(4), following the\nMandal Commission), plus political reservation under Articles 330 and 332.\n• 3. Linguistic Rights [1.5 Marks]:\n- The Eighth Schedule recognises 22 languages; the Constitution permits states to adopt official languages and protects\nlinguistic minorities under Articles 29 and 30 and the three-language formula.\n• 4. Minority and Tribal Provisions [1.5 Marks]:\n- Articles 25–30 guarantee freedom of religion and the right of minorities to establish and administer their own\neducational institutions; the Fifth and Sixth Schedules provide autonomy for tribal areas.",
