        "explanation": "Step-by-Step Marking Scheme (1.5 Marks overview + 3 Marks four phases + 1.5 Marks factors in declining growth):\n• 1. Overview [1.5 Marks]:\n\n- India's population grew from about 361 million in 1951 to 1210 million in 2011, making it the second most populous\ncountry in the world.\n• 2. The Four Phases [3 Marks - 0.75 Mark each]:\n- Phase I (1901-1921): Stagnant population; growth was negative in some decades due to famines, influenza epidemics,\nand plague.\n- Phase II (1921-1951): Steady growth as mortality declined after 1921 ('Year of the Great Divide').\n- Phase III (1951-1981): Rapid 'population explosion' as death rates fell sharply while birth rates remained high.\n- Phase IV (1981-2011): Growth continued but the rate of increase began declining as fertility fell.\n• 3. Factors in Declining Growth [1.5 Marks]:\n- Successful family planning programmes, rising female literacy, later age at marriage, urbanisation, and greater\nawareness of small family norms."
