        "answer": "Detailed analysis: Migration as a component of population change; (1) Internal migration (intra-state and inter-\nstate, rural-urban, rural-rural, urban-urban); (2) International migration (emigration to Gulf, USA, UK; immigration\nfrom Bangladesh, Nepal); (3) Causes: push factors (agrarian distress, land fragmentation) and pull factors\n(employment, education, urban amenities); (4) Consequences: urbanisation, slum growth, remittances, labour\nshortages in rural areas, brain drain.\nStep-by-Step Marking Scheme (1.5 Marks internal vs international migration + 1.5 Marks types of internal migration + 1.5\nMarks causes + 1.5 Marks consequences):\n• 1. Internal versus International Migration [1.5 Marks]:\n- Internal migration occurs within national boundaries (rural-urban, inter-state); international migration crosses national\nboundaries (emigration and immigration).\n\n• 2. Types of Internal Migration [1.5 Marks]:\n- Rural-to-rural (marriage, agricultural labour), rural-to-urban (employment), urban-to-urban (job transfers), and inter-\nstate migration.\n• 3. Causes [1.5 Marks]:\n- Push factors: agrarian distress, land fragmentation, unemployment, drought, and natural disasters.\n- Pull factors: industrial jobs, higher wages, education, healthcare, and urban amenities.\n• 4. Consequences [1.5 Marks]:\n- Urbanisation and informal-sector growth, slum expansion, remittance inflows to rural areas, labour shortages in villages,\nand brain drain at the international level.",
