        "tag": "CBSE 2021 - 4/6 Marks",
        "question": "Discuss the 'National Population Policy 2000'. Examine its objectives, strategies, and the challenges in achieving population\nstabilisation in India. [6 Marks]",
        "answer": "Comprehensive review: Context of population growth; Objectives (stable population by 2045, reduce TFR to\nreplacement level, address unmet contraceptive needs); Strategies (free reproductive health services, universal\neducation, delay in marriage, women's empowerment, decentralised planning); Challenges (regional disparity,\nlow female literacy, unmet contraceptive need, weak implementation, son preference); Evaluation.\nStep-by-Step Marking Scheme (1.5 Marks context & objectives + 2 Marks strategies + 1.5 Marks challenges + 1 Mark\nevaluation):\n• 1. Context and Objectives [1.5 Marks]:\n- Launched to address rapid population growth; aims to achieve a stable population by 2045, reduce the Total Fertility\nRate to replacement level (2.1), and meet unmet contraceptive needs.\n• 2. Strategies [2 Marks]:\n- Free and universal access to reproductive and child health services.\n- Universalisation of primary and secondary education, especially for girls; raising the age at marriage; empowering\nwomen.\n- Decentralised district-level planning and involvement of panchayats.\n• 3. Challenges [1.5 Marks]:\n- Persistent regional disparities, low female literacy in northern states, high unmet need for contraception, and\nentrenched son preference.\n• 4. Evaluation [1 Mark]:\n- The policy represents a shift from coercive targets to a voluntary, rights-based approach focused on human\ndevelopment.",
