        "question": "Examine the 'Scheduled Castes and Scheduled Tribes' demographic profile of India. Discuss their population size, distribution,\nliteracy levels, and the socio-economic challenges they face. [6 Marks]",
        "answer": "Comprehensive examination: Population size (SCs 16.6%, STs 8.6% as per 2011); (1) Distribution (SCs concentrated\nin Uttar Pradesh, West Bengal, Bihar; STs in north-eastern states, Madhya Pradesh, Odisha, Jharkhand); (2)\nLiteracy gap (SCs 66.1%, STs 59%); (3) Challenges: landlessness, poverty, malnutrition, displacement of tribals due\nto development projects, untouchability; (4) Constitutional safeguards and affirmative action.\nStep-by-Step Marking Scheme (1.5 Marks population size & distribution + 1.5 Marks literacy gap + 2 Marks socio-economic\nchallenges + 1 Mark safeguards):\n• 1. Population Size and Distribution [1.5 Marks]:\n- Scheduled Castes constitute about 16.6 percent and Scheduled Tribes about 8.6 percent of India's population (2011).\n- SCs are concentrated in the Indo-Gangetic plains; STs are concentrated in the north-eastern states, central India, and\nOdisha.\n\n• 2. Literacy Gap [1.5 Marks]:\n- SC literacy (66.1 percent) and ST literacy (59 percent) remain below the national average, with female literacy\nsignificantly lower still.\n• 3. Socio-Economic Challenges [2 Marks]:\n- Landlessness, bonded labour, poverty, malnutrition, and high infant and maternal mortality.\n- Displacement of tribal communities due to dams, mining, and industrial projects; continuation of untouchability and\nsocial exclusion.\n• 4. Safeguards [1 Mark]:\n- Constitutional reservations in education, employment, and legislatures (Articles 15(4), 16(4), 330, 332) and the\nPrevention of Atrocities Act.",
