        "tag": "CBSE 2019 - 4/6 Marks",
        "question": "Analyse the relationship between population growth and economic development in India. Is India's large population a resource\nor a burden? [6 Marks]",
        "answer": "Critical analysis: Theoretical perspectives (Malthusian pessimism vs Boserup's optimism vs human capital theory);\n(1) Population as resource: demographic dividend, large labour force, consumer market, innovation potential; (2)\nPopulation as burden: pressure on land, food, water, employment, infrastructure, environment; (3) India's\nspecific context: high population density but low per capita income; (4) Conclusion: population is a resource only\nwith investment in human capital.\nStep-by-Step Marking Scheme (1.5 Marks theoretical perspectives + 1.5 Marks population as resource + 1.5 Marks\npopulation as burden + 1.5 Marks synthesis):\n• 1. Theoretical Perspectives [1.5 Marks]:\n- Malthus warned that population grows geometrically while food grows arithmetically; Boserup argued population\npressure stimulates technological innovation; human capital theory views people as an asset.\n• 2. Population as Resource [1.5 Marks]:\n- A young workforce offers a demographic dividend; a large population provides a vast consumer market, labour supply,\nand innovation potential.\n• 3. Population as Burden [1.5 Marks]:\n- High density creates pressure on agricultural land, food security, water, housing, employment, and the environment,\ncontributing to urban slums and poverty.\n• 4. Synthesis [1.5 Marks]:\n- Population is neither purely a resource nor a burden; it becomes an asset only when accompanied by education, health,\nskilling, and employment generation.",
        "explanation": ""
