        "answer": "Comprehensive examination: Definition of urban (Census criteria: 5000+ population, 75%+ male workers in non-\nagriculture, density 400+ per sq km); (1) Trends (31.2% urban in 2011); (2) Drivers: natural increase, rural-urban\nmigration, reclassification of villages, emergence of new towns; (3) Consequences: urban growth, slums, informal\nsector, strain on services; (4) Impact on rural areas: remittances, labour shortage, feminisation of agriculture.\nStep-by-Step Marking Scheme (1.5 Marks definition & trends + 1.5 Marks drivers of urbanisation + 1.5 Marks urban\nconsequences + 1.5 Marks rural consequences):\n• 1. Definition and Trends [1.5 Marks]:\n- Urban areas are defined by the Census as places with 5000+ population, density of 400+ persons per sq km, and 75\npercent of male workers in non-agricultural pursuits.\n- India's urban population rose to 31.2 percent in 2011.\n\n• 2. Drivers of Urbanisation [1.5 Marks]:\n- Natural population increase, rural-urban migration, reclassification of rural settlements, and the growth of new towns\nand peri-urban areas.\n• 3. Urban Consequences [1.5 Marks]:\n- Growth of slums and informal-sector employment, strain on water, sanitation, transport, and housing, and\nenvironmental degradation.\n• 4. Rural Consequences [1.5 Marks]:\n- Remittance inflows raise rural incomes, but labour shortages and the feminisation of agriculture emerge as able-bodied\nmen migrate.",
