        "question": "\"The demographic profile of India reveals both remarkable achievements and persistent structural inequalities.\" Evaluate this\nstatement with reference to health, education, gender, and regional indicators. [6 Marks]",
        "answer": "Critical evaluation: Achievements (rising life expectancy, declining IMR/MMR, near-replacement TFR, improved\nliteracy); Persistent inequalities (gender gap in literacy and health, adverse sex ratio, regional disparity between\nnorth and south, rural-urban gap); (1) Health indicators; (2) Education indicators; (3) Gender indicators; (4)\nRegional indicators; Synthesis: need for human development-centred policy.\nStep-by-Step Marking Scheme (1.5 Marks achievements + 1.5 Marks gender inequality + 1.5 Marks regional inequality + 1.5\nMarks synthesis & policy implications):\n• 1. Demographic Achievements [1.5 Marks]:\n- Life expectancy rose from about 32 years (1951) to over 69 years; IMR and MMR declined substantially; the Total\nFertility Rate approached replacement level (2.0); literacy rose to 74 percent.\n• 2. Gender Inequality [1.5 Marks]:\n- Despite progress, female literacy (65.46 percent) lags behind male literacy, the sex ratio remains adverse (943), and\nmaternal health indicators are poor.\n• 3. Regional Inequality [1.5 Marks]:\n- Southern states (Kerala, Tamil Nadu) have completed demographic transition while northern states (Bihar, Uttar\nPradesh) still have high fertility, low literacy, and adverse sex ratios.\n• 4. Synthesis and Policy [1.5 Marks]:\n- India's demographic profile reflects both success and unfinished tasks; policy must shift from population control to\nhuman development — female education, health access, and regional equity.",
