        "answer": "Comprehensive analysis: Kinship as a system of social relationships; (1) Lineage and gotra (descent groups,\nexogamy rules, sapinda relationships); (2) Clan and kin terminology; (3) North Indian kinship: bilateral kindred,\ncaste endogamy with gotra exogamy, prohibition of cousin marriage, elaborate terminology distinguishing affinal\nand consanguineal kin; (4) South Indian kinship: preference for cross-cousin marriage, different terminology,\nregional variation; (5) Functions of kinship: regulating marriage, inheritance, and social support.\nStep-by-Step Marking Scheme (1.5 Marks lineage/gotra/clan + 1.5 Marks North Indian kinship + 1.5 Marks South Indian\nkinship + 1.5 Marks functions of kinship):\n• 1. Lineage, Gotra, and Clan [1.5 Marks]:\n- A lineage is a unilineal descent group tracing common ancestry; a gotra is an exogamous clan segment used to regulate\nmarriage; a clan is a wider descent group claiming common mythical ancestry.\n• 2. North Indian Kinship [1.5 Marks]:\n- Follows caste endogamy with gotra exogamy; prohibits marriage within the same gotra and between sapindas;\ndistinguishes sharply between consanguineal and affinal kin in terminology.\n• 3. South Indian Kinship [1.5 Marks]:\n- Permits and often prefers cross-cousin marriage (particularly the marriage of a girl to her mother's brother); kinship\nterminology reflects the permissibility of such alliances.\n• 4. Functions of Kinship [1.5 Marks]:\n- Regulates marriage and incest prohibitions, governs inheritance and succession, provides social security, and structures\neconomic cooperation.",
