        "question": "Analyse the debate around a 'Uniform Civil Code' in India. Discuss the arguments for and against it, with reference to gender\njustice, minority rights, and the constitutional vision of secularism. [6 Marks]",
        "answer": "Comprehensive analysis: Constitutional context (Article 44, Directive Principles); Arguments in favour (gender\njustice, national integration, uniform citizenship rights, end to discriminatory personal laws); Arguments against\n(minority rights, religious freedom under Articles 25-28, cultural autonomy, fear of majoritarian imposition);\n\nLandmark case law (Shah Bano 1985, Sarla Mudgal 1995, Shayara Bano 2017); Sociological synthesis.\nStep-by-Step Marking Scheme (1.5 Marks constitutional context + 2 Marks arguments in favour + 2 Marks arguments\nagainst + 0.5 Mark case law/synthesis):\n• 1. Constitutional Context [1.5 Marks]:\n- Article 44 of the Directive Principles directs the state to endeavour to secure a uniform civil code; the debate centres on\nwhether this should override community-specific personal laws.\n• 2. Arguments in Favour [2 Marks]:\n- A common code would ensure equal rights for all citizens irrespective of religion, particularly benefiting women\nsubjected to discriminatory practices like triple talaq and unequal inheritance.\n- It would promote national integration and a single standard of citizenship rights.\n• 3. Arguments Against [2 Marks]:\n- It may violate religious freedom under Articles 25–28 and undermine the cultural autonomy of minorities in a plural\nsociety.\n- Critics argue it could become an instrument of majoritarian cultural imposition.\n• 4. Case Law and Synthesis [0.5 Mark]:\n- Shah Bano (1985), Sarla Mudgal (1995), and Shayara Bano (2017) highlight the tension between personal laws and\ngender justice.",
