        "answer": "Comprehensive analysis: Caste endogamy as the mechanism of caste reproduction (Ambedkar's view that\nendogamy is the essence of caste); (1) Mechanisms: caste panchayats, honour killings, matrimonial\nadvertisements by caste, kinship networks; (2) Functions: preserving property, ritual purity, and caste solidarity;\n(3) Challenges: inter-caste marriages, love marriages, urban anonymity, education, legal protection (Special\nMarriage Act 1954), state incentives for inter-caste marriage (Dr. Ambedkar Scheme); (4) Sociological evaluation:\nendogamy persists despite change.\nStep-by-Step Marking Scheme (1.5 Marks caste endogamy & Ambedkar + 1.5 Marks mechanisms of enforcement + 1.5\nMarks challenges to endogamy + 1.5 Marks evaluation):\n• 1. Caste Endogamy [1.5 Marks]:\n- B.R. Ambedkar argued that endogamy is the very foundation of caste; by confining marriage within the group, caste\nproduces and reproduces itself as a closed class.\n• 2. Mechanisms of Enforcement [1.5 Marks]:\n- Caste panchayats policing marriages, matrimonial advertisements specifying caste, khap panchayats, and in extreme\ncases 'honour killings'.\n• 3. Challenges to Endogamy [1.5 Marks]:\n- Rising inter-caste and love marriages in urban areas, education and occupational mobility, anonymity of city life, the\nSpecial Marriage Act 1954, and state incentive schemes for inter-caste marriage.\n• 4. Evaluation [1.5 Marks]:\n- Despite legal and social changes, endogamy remains the dominant pattern, showing the resilience of caste in marriage.",
