        "answer": "Comprehensive examination: Rituals as institutionalised symbolic action; (1) Life-cycle rites (samskaras:\nnamakarana, upanayana, vivaha, antyeshti; birth, puberty, marriage, death rituals); (2) Domestic rituals (daily\npuja, ancestor worship, shraddha); (3) Festivals (Diwali, Holi, Eid, Christmas, Onam, Pongal, Bihu) as community\nintegration mechanisms; (4) Functions: reinforcing kinship bonds, transmitting values, marking social status,\n\ncreating collective solidarity (Durkheim's collective conscience); (5) Change: secularisation, commodification, and\ndiaspora adaptation.\nStep-by-Step Marking Scheme (1.5 Marks life-cycle rites + 1.5 Marks domestic rituals + 1.5 Marks festivals & community\nintegration + 1.5 Marks sociological functions & change):\n• 1. Life-Cycle Rites [1.5 Marks]:\n- Samskaras such as namakarana (naming), upanayana (sacred thread), vivaha (marriage), and antyeshti (funeral) mark\ntransitions in the life course and define social identity.\n• 2. Domestic Rituals [1.5 Marks]:\n- Daily worship, ancestor worship (shraddha), and household festivals reinforce the sacred character of the family and the\ncontinuity of lineage.\n• 3. Festivals and Community Integration [1.5 Marks]:\n- Festivals bring together extended kin and the wider community, cutting across caste and class lines, and reaffirm shared\ncultural identity.\n• 4. Sociological Functions and Change [1.5 Marks]:\n- Following Durkheim, rituals reinforce the collective conscience and social solidarity; contemporary secularisation,\ncommodification, and diaspora adaptation are reshaping their form.",
