        "answer": "Critical evaluation: Dual character of the family institution; (1) Support: emotional security, childcare,\nsocialisation, care for the elderly and the sick, economic pooling; (2) Oppression: patriarchal authority, son\npreference, dowry, domestic violence, unpaid reproductive labour, restricted mobility, control over sexuality; (3)\nLegal and social change: Hindu Succession Act 2005, Domestic Violence Act 2005, POSH Act 2013, women's\neducation and employment; (4) Synthesis: the family remains ambivalent, requiring structural change beyond\nlegal reform.\nStep-by-Step Marking Scheme (1.5 Marks family as support + 2 Marks family as site of oppression + 1.5 Marks legal and\nsocial change + 1 Mark synthesis):\n• 1. Family as Support [1.5 Marks]:\n- Provides emotional security, primary socialisation of children, care for children, the elderly, and the sick, and pools\neconomic resources and risk.\n• 2. Family as Site of Oppression [2 Marks]:\n- Patriarchal authority, son preference and female foeticide, dowry harassment, domestic violence, and the burden of\nunpaid domestic and reproductive labour restrict women's autonomy.\n• 3. Legal and Social Change [1.5 Marks]:\n- The Hindu Succession (Amendment) Act 2005, the Protection of Women from Domestic Violence Act 2005, the POSH\nAct 2013, and rising female education and employment have expanded women's rights.\n• 4. Synthesis [1 Mark]:\n- The family remains an ambivalent institution; achieving gender equality requires transformation of social norms, not\nmerely legal reform.",
