        "answer": "Comprehensive analysis: Markets as socially embedded (Polanyi); (1) Caste and community in markets:\noccupational specialisation of trading castes, trust and reputation networks, hundi system, Marwari and Chettiar\nbanking networks; (2) Gender in markets: purdah restricting women's participation, gendered division of market\nlabour, women in informal and home-based work; (3) State and markets: colonial trade policy,\ndeindustrialisation, post-1991 liberalisation, regulation of labour and consumer protection; (4) Conclusion:\nmarkets are culturally and socially organised, not natural.\nStep-by-Step Marking Scheme (1.5 Marks theoretical embeddedness + 1.5 Marks caste/community networks + 1.5 Marks\ngender and markets + 1.5 Marks state and market history):\n• 1. Theoretical Embeddedness [1.5 Marks]:\n- Following Karl Polanyi, sociologists reject the notion of a natural self-regulating market; markets are embedded in social\nrelations, norms, and institutions.\n• 2. Caste and Community Networks [1.5 Marks]:\n- Traditional trade and banking were dominated by specific communities — Marwaris, Nattukottai Chettiars, Banias,\nBohras — whose caste networks supplied trust, credit, and contract enforcement through instruments like the hundi.\n• 3. Gender and Markets [1.5 Marks]:\n- Gendered norms of seclusion (purdah) restricted women's access to public markets; women's market participation is\nconcentrated in low-paid informal, home-based, and agricultural work.\n• 4. State and Market History [1.5 Marks]:\n- Colonial policy deindustrialised Indian handicrafts and integrated India into the capitalist world economy; post-1991\nliberalisation deregulated markets but also intensified inequality and consumerism.",
