        "answer": "Comprehensive examination: Context of the 1991 balance of payments crisis; (1) Liberalisation: dismantling of\nlicence-permit raj, trade liberalisation, deregulation; (2) Privatisation: disinvestment, entry of MNCs, contraction\nof public sector; (3) Globalisation: FDI, WTO regime, global supply chains, IT boom; (4) Impact on agriculture:\nexposure to global prices, agrarian distress, farmer suicides; (5) Impact on industry and employment: formal\nsector growth but informalisation; (6) Consumption: consumerism, mall culture, advertising; (7) Sociological\nconsequences: rising inequality, new middle class, regional disparity, cultural change.\nStep-by-Step Marking Scheme (1.5 Marks context & policy content + 1.5 Marks impact on agriculture + 1.5 Marks impact\non industry and employment + 1.5 Marks sociological consequences):\n• 1. Context and Policy Content [1.5 Marks]:\n- Triggered by the 1991 balance of payments crisis, the LPG reforms dismantled the licence-permit system, reduced\ntariffs, encouraged FDI, and opened India to global capital.\n• 2. Impact on Agriculture [1.5 Marks]:\n- Farmers were exposed to volatile global prices, reduced subsidies under the WTO regime, and rising input costs,\ncontributing to agrarian distress and farmer suicides.\n• 3. Impact on Industry and Employment [1.5 Marks]:\n- Growth of IT, services, and consumer industries; however, employment growth remained sluggish and informal, casual,\nand contract work expanded ('informalisation of the formal sector').\n• 4. Sociological Consequences [1.5 Marks]:\n- Emergence of a new consuming middle class, widening income inequality, regional disparities, cultural consumerism,\n\nand the erosion of public-sector welfare commitments.",
