        "answer": "Comprehensive review: Pre-colonial market structure (artisanal production, periodic markets, indigenous\nbanking, hundi); (1) Colonial trade policy: one-way free trade, destruction of Indian textiles; (2)\nDeindustrialisation: loss of patronage, machine competition, artisan pauperisation; (3) Railway and market\nintegration: commercialisation of agriculture, raw material export; (4) Emergence of new classes: Indian\ncomprador bourgeoisie, Marwari industrialists, working class; (5) Sociological consequences: ruralisation of India,\nstructural poverty.\nStep-by-Step Marking Scheme (1.5 Marks pre-colonial market structure + 1.5 Marks deindustrialisation + 1.5 Marks\nintegration into world economy + 1.5 Marks new classes and consequences):\n• 1. Pre-Colonial Market Structure [1.5 Marks]:\n- A flourishing artisanal economy, periodic rural markets, long-distance trade, and sophisticated indigenous credit\nsystems such as the hundi operated through merchant communities.\n• 2. Deindustrialisation [1.5 Marks]:\n- One-way free trade allowed cheap machine-made British goods to flood Indian markets while Indian handicrafts lost\nboth royal patronage and export markets.\n- Artisans were pauperised and forced into agriculture, increasing pressure on land.\n• 3. Integration into the World Economy [1.5 Marks]:\n- India became a supplier of raw materials (cotton, jute, indigo) and a consumer of British manufactures; railways and\nports integrated internal markets with the imperial economy and commercialised agriculture.\n• 4. New Classes and Consequences [1.5 Marks]:\n- Emergence of an Indian comprador bourgeoisie, Marwari industrialists, and an industrial working class; the overall result\nwas the 'ruralisation' of India and structural impoverishment.",
