        "question": "Analyse the role of 'Gender' in markets. How do patriarchal norms shape women's participation in economic activity, and how\nhas globalisation affected women's work? [6 Marks]",
        "answer": "Comprehensive analysis: Gendered nature of markets; (1) Constraints on women: purdah, restricted mobility,\ngendered division of labour, unpaid reproductive work; (2) Occupational segregation: women concentrated in\nlow-paid informal, agricultural, and home-based work; (3) Wage discrimination and glass ceiling; (4) Globalisation\neffects: export-oriented garment and electronics industries employing young women, maquila-type employment,\nnew consumerist aspirations, double burden; (5) Empowerment possibilities: SHGs, women entrepreneurs,\neducation.\nStep-by-Step Marking Scheme (1.5 Marks patriarchal constraints + 1.5 Marks occupational segregation + 1.5 Marks\nglobalisation effects + 1.5 Marks empowerment and critique):\n• 1. Patriarchal Constraints [1.5 Marks]:\n- Norms of seclusion (purdah), restricted mobility, and the sexual division of labour confine women to the domestic\nsphere and undervalue their work.\n• 2. Occupational Segregation [1.5 Marks]:\n- Women are concentrated in low-paid, insecure informal sector work — agriculture, home-based piecework, domestic\nservice — with lower wages and little social protection.\n• 3. Globalisation Effects [1.5 Marks]:\n- Export-oriented industries (garments, electronics, food processing) have drawn young women into factory employment,\nbut often in exploitative conditions with a 'double burden' of paid and unpaid work.\n\n• 4. Empowerment and Critique [1.5 Marks]:\n- SHGs, rising female education, and women's entrepreneurship have enhanced autonomy; however, market integration\nalone does not dismantle patriarchal structures.",
