        "answer": "Comprehensive examination: Consumerism as a cultural-economic phenomenon; (1) Advertising: creation of\ndesires, brand identity, lifestyle marketing, targeting of children; (2) Growth of the middle class: liberalisation,\ndual incomes, credit culture, mall culture; (3) Commodification of festivals, education, and relationships; (4)\nSociological consequences: status competition, environmental degradation, exclusion of the poor, erosion of\ntraditional values, global-local cultural hybridisation; (5) Consumer movement as a response.\nStep-by-Step Marking Scheme (1.5 Marks advertising and desire creation + 1.5 Marks middle class and credit culture + 1.5\nMarks commodification + 1.5 Mark sociological consequences & consumer movement):\n• 1. Advertising and Desire Creation [1.5 Marks]:\n- Advertising does not merely inform but manufactures desires, linking commodities to aspirations of beauty, status,\nsuccess, and modernity, and increasingly targets children.\n• 2. Middle Class and Credit Culture [1.5 Marks]:\n- Liberalisation, dual incomes, easy credit cards and EMI schemes, and the growth of malls and e-commerce have fuelled\na consumerist middle class.\n• 3. Commodification [1.5 Marks]:\n- Festivals, education, healthcare, and even personal relationships are increasingly mediated by market transactions and\nbrand logic.\n• 4. Consequences and Consumer Movement [1.5 Marks]:\n- Consumerism produces status competition, environmental stress, and social exclusion, while simultaneously generating\na consumer rights movement demanding safety, information, and redressal.",
