        "answer": "Comprehensive examination: Pre-modern credit institutions; (1) The hundi system: bill of exchange, trust-based,\noperated through merchant communities (Marwaris, Chettiars, Bhatias); (2) Indigenous bankers: multani bankers,\nshroffs, seths; functions: credit, remittance, currency exchange, financing trade; (3) Colonial period: decline due\nto British joint-stock banks, railways, and changing trade routes; (4) Post-independence: nationalisation of banks\n(1969, 1980), cooperative banks, RRBs; (5) Contemporary: microfinance, SHG-bank linkage, digital payments.\nStep-by-Step Marking Scheme (1.5 Marks hundi system + 1.5 Marks indigenous bankers + 1.5 Marks decline under\ncolonialism + 1.5 Marks post-independence banking):\n• 1. The Hundi System [1.5 Marks]:\n- A traditional Indian bill of exchange or promissory note that enabled credit transfer and remittance across long\ndistances based on community trust and reputation.\n• 2. Indigenous Bankers [1.5 Marks]:\n- Multani bankers, shroffs, and merchant communities (Marwaris, Nattukottai Chettiars, Bhatias) financed trade,\ndiscounted hundis, and provided credit in both rural and urban markets.\n• 3. Decline under Colonialism [1.5 Marks]:\n- The expansion of British joint-stock banks, changes in trade routes, and colonial monetary policy undermined indigenous\nbanking networks.\n• 4. Post-Independence Banking [1.5 Marks]:\n- Nationalisation of major banks (1969 and 1980), expansion of cooperative banks and regional rural banks, and more\nrecently microfinance, SHG-bank linkage, and digital payment systems have reshaped credit access.",
