        "answer": "Comprehensive examination: Definition and characteristics of periodic markets (held weekly or fortnightly,\nmobile traders, perishable and low-value goods); (1) Economic functions: access to goods in areas without\npermanent shops, price discovery, outlet for surplus and artisanal products; (2) Social functions: meeting place for\ndispersed villages, information exchange, marriage arrangements, entertainment, community integration; (3)\nCaste dimensions: specific castes trading specific commodities, ritual purity norms in exchange; (4) Change:\ndecline due to permanent shops, roads, mobile phones, and e-commerce.\nStep-by-Step Marking Scheme (1.5 Marks definition & economic functions + 1.5 Marks social functions + 1.5 Marks caste\ndimensions + 1.5 Marks contemporary change):\n• 1. Definition and Economic Functions [1.5 Marks]:\n- Periodic markets (haats) are weekly or fortnightly markets held in rotation across villages, providing access to goods,\nprice discovery, and an outlet for local surplus and artisanal products.\n• 2. Social Functions [1.5 Marks]:\n- They serve as crucial social spaces where people from scattered settlements meet, exchange news, arrange marriages,\naccess entertainment, and reinforce community bonds.\n• 3. Caste Dimensions [1.5 Marks]:\n- Specific castes traditionally trade specific commodities; norms of purity and pollution shape transactions, and market\nroles reflect the wider caste division of labour.\n• 4. Contemporary Change [1.5 Marks]:\n- Permanent shops, improved roads, mobile telephony, and e-commerce are reducing the frequency and importance of\nperiodic markets.",
