        "answer": "Critical evaluation: Dual character of market integration; (1) Opportunities: access to larger markets, technology,\nemployment, consumer choice, entrepreneurship; (2) Vulnerabilities for small producers: competition from\nMNCs, displacement of artisans, price volatility, dependence on contract farming; (3) Farmers: exposure to global\ncommodity prices, input cost inflation, debt, and suicides; (4) Workers: informalisation, job insecurity, contract\nlabour, gig economy precarity; (5) Policy implications: need for regulation, social protection, minimum support\nprice, and cooperative strengthening.\nStep-by-Step Marking Scheme (1.5 Marks opportunities + 1.5 Marks small producer vulnerabilities + 1.5 Marks farmer\ndistress + 1.5 Marks worker precarity & policy):\n• 1. Opportunities [1.5 Marks]:\n- Market integration expands access to larger consumer markets, technology, employment, and consumer choice, and\nenables entrepreneurship and upward mobility.\n• 2. Small Producer Vulnerabilities [1.5 Marks]:\n- Artisans and small producers face competition from cheap machine-made and imported goods, displacement, price\nvolatility, and dependence on corporate buyers.\n• 3. Farmer Distress [1.5 Marks]:\n- Liberalisation exposed farmers to global price fluctuations and reduced procurement support while input costs rose,\n\ncontributing to indebtedness and suicides.\n• 4. Worker Precarity and Policy [1.5 Marks]:\n- Informalisation, contract labour, and gig economy precarity have increased vulnerability; policy responses require MSP\nguarantees, social security, labour code enforcement, and cooperative support.",
