        "id": 50,
        "type": "LA",
        "tag": "CBSE 2017 - 4/6 Marks",
        "question": "\"India's cultural diversity is its greatest strength as well as its greatest challenge.\" Critically evaluate this statement with\nreference to the constitutional management of diversity and the contemporary threats to pluralism. [6 Marks]",
        "answer": "Critical evaluation: Dual character of diversity; (1) As strength: civilisational richness, adaptive capacity, pluralist\nconstitutionalism, cultural innovation, democratic vitality; (2) As challenge: communalism, regionalism, linguistic\nconflicts, identity politics, separatist extremism; (3) Constitutional management: fundamental rights, linguistic\nfederalism, personal laws, minority rights, Fifth/Sixth Schedules; (4) Contemporary threats: majoritarianism,\npolarised media, economic exclusion of minorities, erosion of deliberative politics; (5) Conclusion: diversity\nrequires active democratic nurturing, not passive tolerance.\n\nStep-by-Step Marking Scheme (1.5 Marks diversity as strength + 1.5 Marks diversity as challenge + 1.5 Marks constitutional\nmanagement + 1.5 Marks contemporary threats & conclusion):\n• 1. Diversity as Strength [1.5 Marks]:\n- India's pluralism is a civilisational resource providing cultural richness, social adaptability, innovative hybridity, and a\npluralist democratic tradition.\n• 2. Diversity as Challenge [1.5 Marks]:\n- It can be mobilised into communalism, regional chauvinism, linguistic conflict, and secessionist politics.\n• 3. Constitutional Management [1.5 Marks]:\n- Fundamental rights, linguistic federalism, community-specific personal laws, minority rights under Articles 29–30, and\nthe Fifth/Sixth Schedules provide institutional accommodation.\n• 4. Contemporary Threats and Conclusion [1.5 Marks]:\n- Majoritarian politics, polarised media, and minority economic exclusion threaten pluralism; sustaining diversity requires\nactive democratic commitment, inclusive development, and protection of dissent.",
        "explanation": ""
