        "answer": "Comprehensive examination: Industrialisation as structural transformation; (1) Colonial phase:\ndeindustrialisation, limited factory industry in textiles and jute around port cities, exploitative labour conditions;\n(2) Post-independence phase: Nehru-Mahalanobis heavy industry strategy, public sector, import substitution,\nlicensing; (3) Post-1991 phase: liberalisation, services-led growth, IT boom, informalisation; (4) Social impact:\nurbanisation, working-class formation, decline of caste-based occupations, women's employment, migration; (5)\nChallenges: regional concentration, informal sector dominance, environmental costs, labour precarity.\nStep-by-Step Marking Scheme (1.5 Marks colonial phase + 1.5 Marks post-independence phase + 1.5 Marks social impact +\n1.5 Marks challenges):\n• 1. Colonial Phase [1.5 Marks]:\n- Deindustrialisation of handicrafts; limited factory growth in cotton textiles and jute concentrated around Bombay and\nCalcutta, with exploitative labour conditions and absence of capital goods industry.\n• 2. Post-Independence Phase [1.5 Marks]:\n- The Nehru–Mahalanobis strategy emphasised heavy industry, public sector leadership, and import substitution under\nthe licence-permit regime.\n- Post-1991 liberalisation shifted towards private capital, FDI, and services-led growth, including the IT boom.\n• 3. Social Impact [1.5 Marks]:\n- Urbanisation, formation of an industrial working class, decline of caste-based occupations, increased women's factory\n\nemployment, and large-scale rural-urban migration.\n• 4. Challenges [1.5 Marks]:\n- Regional concentration of industry, dominance of the informal sector with insecure work, environmental degradation,\nand displacement due to industrial projects.",
