        "question": "Discuss 'Urbanisation' as a process of structural change in India. Examine its causes, patterns, and socio-economic\nconsequences. [6 Marks]",
        "answer": "Comprehensive examination: Urbanisation as a structural transformation; (1) Causes: industrialisation, rural-\nurban migration, natural increase, reclassification of settlements, administrative growth; (2) Patterns: growth of\nmetropolitan cities and mega-cities, uneven regional distribution, emergence of peri-urban areas; (3) Socio-\neconomic consequences: shift from agriculture to non-agricultural occupations, slums and informal settlements,\nstrain on urban services, improved access to education and health, changing family structures, cultural change; (4)\nChallenges: housing, water, sanitation, transport, pollution, unemployment; (5) Policy responses.\nStep-by-Step Marking Scheme (1.5 Marks causes + 1.5 Marks patterns + 1.5 Marks socio-economic consequences + 1.5\nMarks challenges & policy):\n• 1. Causes [1.5 Marks]:\n- Industrialisation and service-sector growth, rural-urban migration driven by agrarian distress, natural population\nincrease, reclassification of villages as towns, and expansion of administrative and educational centres.\n• 2. Patterns [1.5 Marks]:\n- Concentration in metropolitan and mega-cities, uneven regional distribution favouring the western and southern\nregions, and the growth of peri-urban and satellite towns.\n• 3. Socio-Economic Consequences [1.5 Marks]:\n- Occupational shift away from agriculture, proliferation of slums and informal employment, strain on civic services, but\nalso improved access to education, health, and mobility, along with changing family and cultural patterns.\n• 4. Challenges and Policy [1.5 Marks]:\n- Housing shortages, water and sanitation deficits, transport congestion, pollution, and unemployment; policy responses\ninclude JNNURM, AMRUT, Smart Cities Mission, and Pradhan Mantri Awas Yojana.",
