        "answer": "Comprehensive analysis: Green Revolution as agrarian structural change; (1) Content: HYV seeds, chemical\nfertilisers, pesticides, assured irrigation, mechanisation, institutional credit, minimum support price; (2)\nAchievements: food self-sufficiency, increased productivity, marketable surplus, rural prosperity in selected\nregions; (3) Social costs: agrarian differentiation, displacement of tenants and sharecroppers, intensification of\ncaste and class inequality, mechanisation-induced labour displacement; (4) Ecological costs: water table\ndepletion, soil degradation, pesticide toxicity, loss of biodiversity; (5) Evaluation.\nStep-by-Step Marking Scheme (1.5 Marks content of Green Revolution + 1.5 Marks achievements + 1.5 Marks social costs +\n1.5 Marks ecological costs & evaluation):\n• 1. Content [1.5 Marks]:\n- Introduction of HYV seeds of wheat and rice, chemical fertilisers and pesticides, assured irrigation, mechanisation\n(tractors, tubewells), institutional credit, and minimum support prices.\n• 2. Achievements [1.5 Marks]:\n- Achieved foodgrain self-sufficiency, dramatically increased productivity, generated a marketable surplus, and created\nrural prosperity in Punjab, Haryana, and western Uttar Pradesh.\n• 3. Social Costs [1.5 Marks]:\n\n- Agrarian differentiation between large, middle, and small peasants; displacement of tenants and sharecroppers;\nintensification of caste-class inequality; and labour displacement through mechanisation.\n• 4. Ecological Costs and Evaluation [1.5 Marks]:\n- Groundwater depletion, soil salinisation and degradation, pesticide toxicity, and loss of crop biodiversity; the Green\nRevolution was a technologically successful but socially and ecologically uneven transformation.",
