        "answer": "Comprehensive examination: Globalisation as structural transformation; (1) Economic impact: growth of IT and\nservices, FDI, integration into global supply chains, consumer choice, but also informalisation of labour, agrarian\ndistress, and widening inequality; (2) Cultural impact: consumerism, hybrid cultural forms, media globalisation,\nconcerns about cultural homogenisation; (3) Social impact: emergence of a new middle class, changing family and\ngender relations, migration, and new forms of stratification; (4) Challenges: regional disparity, environmental\ncosts, erosion of sovereignty in economic policy; (5) Evaluation.\nStep-by-Step Marking Scheme (1.5 Marks economic impact + 1.5 Marks cultural impact + 1.5 Marks social impact + 1.5\nMarks challenges & evaluation):\n• 1. Economic Impact [1.5 Marks]:\n- Rapid growth of IT, services, FDI, and integration into global supply chains, alongside informalisation of labour, agrarian\ndistress, and widening income inequality.\n• 2. Cultural Impact [1.5 Marks]:\n- Spread of consumerist lifestyles, global media, and hybrid cultural forms, alongside anxieties about the erosion of local\ncultures and traditions.\n• 3. Social Impact [1.5 Marks]:\n- Emergence of a large consuming middle class, changing gender and family relations, increased migration, and new forms\nof class stratification based on skill and education.\n• 4. Challenges and Evaluation [1.5 Marks]:\n- Regional disparity, environmental costs, and reduced policy autonomy; globalisation is a contradictory process that\ncreates both opportunity and vulnerability.",
