        "question": "Analyse the changes in 'Caste' and 'Class' structures in contemporary India. How have industrialisation, education, and political\ndemocracy transformed traditional caste relations? [6 Marks]",
        "answer": "Comprehensive analysis: Caste as traditional hierarchy; (1) Transformations: occupational mobility,\nsanskritisation, politicisation of caste, rise of OBC and Dalit assertion, inter-caste marriage in urban areas; (2) Role\nof education: opening non-caste occupations, individual merit, weakening of ritual authority; (3) Role of\ndemocracy: universal adult franchise, caste-based political mobilisation, reservations, Mandal politics; (4)\nEmergence of class: new middle class, capitalist farmers, working class, and corporate elite; (5) Persistence:\nendogamy, caste violence, caste associations; (6) Evaluation.\nStep-by-Step Marking Scheme (1.5 Marks transformations of caste + 1.5 Marks role of education + 1.5 Marks role of\ndemocracy & politicisation + 1.5 Marks class emergence & persistence):\n• 1. Transformations of Caste [1.5 Marks]:\n- Occupational mobility, sanskritisation, the rise of caste associations, politicisation of caste, and greater assertion by\nOBCs and Dalits.\n• 2. Role of Education [1.5 Marks]:\n- Modern education opened non-caste-based occupations and created a framework of individual achievement,\nweakening the ritual authority of Brahmins.\n• 3. Role of Democracy [1.5 Marks]:\n- Universal adult franchise transformed caste into a political resource; reservations and the Mandal Commission\npoliticised OBC identity, while Dalit movements gained visibility.\n• 4. Class Emergence and Persistence [1.5 Marks]:\n- New class formations — capitalist farmers, middle class, working class, corporate elite — emerged alongside caste; yet\nendogamy, caste violence, and matrimonial caste preferences persist.",
        "explanation": ""
