        "answer": "Comprehensive examination: Traditional joint family structure; (1) Structural changes: nuclearisation, decline of\npatriarchal authority, dual-earner households, changing marriage and divorce patterns, single-parent and live-in\nrelationships; (2) Factors: industrialisation, urbanisation, migration, education, women's employment, legal\nreforms; (3) Impact on gender relations: greater autonomy and negotiation, but persistence of the 'double\nburden' and domestic violence; (4) Impact on elder care: old-age insecurity, loneliness, need for institutional care;\n(5) Evaluation.\nStep-by-Step Marking Scheme (1.5 Marks structural changes + 1.5 Marks factors responsible + 1.5 Marks gender relations\nimpact + 1.5 Marks elder care & evaluation):\n• 1. Structural Changes [1.5 Marks]:\n- Nuclearisation, declining patriarchal authority, dual-earner households, later marriage, rising divorce, and greater\nacceptance of single-parent and non-traditional arrangements.\n• 2. Factors Responsible [1.5 Marks]:\n- Industrialisation, urbanisation, occupational migration, women's education and employment, and legal reforms in\n\nmarriage, inheritance, and divorce.\n• 3. Impact on Gender Relations [1.5 Marks]:\n- Increased female autonomy and voice in decision-making, but the 'double burden' of paid and unpaid work and\ndomestic violence persist.\n• 4. Elder Care and Evaluation [1.5 Marks]:\n- Nuclear families have weakened traditional elder care, producing old-age insecurity and loneliness; policy responses\ninclude pension schemes and maintenance legislation.",
