        "answer": "Comprehensive examination: Panchayati raj as decentralised governance; (1) Provisions of 73rd Amendment\n(1992): three-tier structure (Gram Panchayat, Panchayat Samiti, Zila Parishad), mandatory elections every five\nyears, reservations for SCs/STs and one-third for women, State Election Commissions, State Finance Commissions,\n29 subjects in the Eleventh Schedule; (2) Impact: political participation of women and marginalised groups,\ngrassroots democracy, rural development; (3) Limitations: lack of financial devolution, state government control,\nSarpanch dominance, low literacy of elected members; (4) Evaluation.\nStep-by-Step Marking Scheme (1.5 Marks concept & significance + 2 Marks 73rd Amendment provisions + 1.5 Marks\nimpact + 1 Mark limitations & evaluation):\n• 1. Concept and Significance [1.5 Marks]:\n- Panchayati raj is a system of decentralised local self-government intended to bring democracy and development to the\nvillage level, deepening participatory governance.\n• 2. Provisions of the 73rd Amendment (1992) [2 Marks]:\n- Three-tier structure: Gram Panchayat, Panchayat Samiti, and Zila Parishad.\n- Mandatory elections every five years, with reservations for SCs and STs and not less than one-third of seats for women.\n- Constitution of State Election Commissions and State Finance Commissions; devolution of 29 subjects listed in the\nEleventh Schedule.\n• 3. Impact [1.5 Marks]:\n- Enhanced political participation of women and marginalised communities, strengthened grassroots democracy, and\nimproved local planning and accountability.\n• 4. Limitations and Evaluation [1 Mark]:\n- Inadequate financial devolution, continued state control, dominance of sarpanches, and low literacy of members limit\nits effectiveness; it represents a significant but incomplete democratic decentralisation.",
