        "answer": "Comprehensive analysis: Definition (M.N. Srinivas); (1) Causes: British colonial rule, English education, new legal\nand administrative institutions, missionary activity, railways and communication; (2) Forms: adoption of Western\ndress, diet, education, legal systems, humanitarian values, secularism, rationalism; (3) Consequences: emergence\nof a new middle class, social reform movements, decline of some traditional practices, but also cultural alienation\nand elitism; (4) Relationship with modernisation: westernisation is a specific historical route to modernisation,\nbut modernisation can occur without westernisation (e.g. Japan); (5) Evaluation.\n\nStep-by-Step Marking Scheme (1.5 Marks causes + 1.5 Marks forms + 1.5 Marks consequences + 1.5 Marks relationship\nwith modernisation & evaluation):\n• 1. Causes [1.5 Marks]:\n- British colonial rule, English-medium education, new legal and administrative institutions, missionary activity, and\nmodern transport and communication.\n• 2. Forms [1.5 Marks]:\n- Adoption of Western dress, diet, education, legal systems, technology, and values such as humanitarianism, secularism,\nand rationalism.\n• 3. Consequences [1.5 Marks]:\n- Emergence of an English-educated middle class, social reform movements challenging caste and patriarchy, decline of\nsome traditional practices, but also cultural alienation and elitist distance from the masses.\n• 4. Relationship with Modernisation and Evaluation [1.5 Marks]:\n- Westernisation was India's historically specific route to modernisation; however, modernisation is analytically broader\nand can occur independently of Western influence, as demonstrated by Japan.",
