        "answer": "Comprehensive examination: Meaning and Western experience; (1) Indian secularism: 'principled distance', sarva\ndharma sambhava, constitutional framework, state intervention to reform religious practices; (2) Indicators:\ndecline of religious authority in personal law reform, education, occupation; growth of scientific temper; (3)\nChallenges: communalism, majoritarianism, political use of religion, religious personal laws, rise of religious\nintolerance; (4) Evaluation: secularisation in India is partial and contested rather than linear.\nStep-by-Step Marking Scheme (1.5 Marks meaning & Western experience + 1.5 Marks Indian model + 1.5 Marks indicators\n+ 1.5 Marks challenges & evaluation):\n• 1. Meaning and Western Experience [1.5 Marks]:\n- In the West, secularisation involved the institutional differentiation of religion from politics, science, and education, and\nthe privatisation of faith.\n• 2. Indian Model [1.5 Marks]:\n- Indian secularism follows 'principled distance' (Rajeev Bhargava) and sarva dharma sambhava, combining state\nequidistance from all religions with active intervention to reform regressive practices (abolition of sati, untouchability,\ntemple entry).\n• 3. Indicators [1.5 Marks]:\n- Decline of religious authority over marriage, occupation, and education; growth of scientific temper; constitutional\nguarantees of religious freedom; and reform of personal laws.\n• 4. Challenges and Evaluation [1.5 Marks]:\n- Communalism, majoritarian politics, political mobilisation of religion, and religious intolerance challenge secularisation;\nin India it is a partial, contested, and non-linear process.",
