        "answer": "Comprehensive examination: Globalisation and cultural flows; (1) Hybridisation: Hinglish, fusion music and\ncuisine, Indo-Western fashion, blended festival celebrations; (2) Glocalisation: adaptation of global products to\nlocal tastes (McDonald's vegetarian menu in India, regional language television); (3) Cultural resistance: revivalist\nmovements, swadeshi campaigns, assertions of regional and religious identity, anti-Western sentiment; (4)\nConsequences: consumerism, changing youth culture, erosion of some traditions, but also global visibility of\n\nIndian culture (yoga, Bollywood); (5) Evaluation.\nStep-by-Step Marking Scheme (1.5 Marks hybridisation + 1.5 Marks glocalisation + 1.5 Marks cultural resistance + 1.5\nMarks consequences & evaluation):\n• 1. Cultural Hybridisation [1.5 Marks]:\n- Globalisation produces blended cultural forms — Hinglish, fusion music and cuisine, Indo-Western fashion, and hybrid\nfestival celebrations.\n• 2. Glocalisation [1.5 Marks]:\n- Global products and practices are adapted to local contexts — McDonald's offering vegetarian menus in India, regional-\nlanguage television, and localised advertising.\n• 3. Cultural Resistance [1.5 Marks]:\n- Globalisation provokes revivalist movements, swadeshi campaigns, assertions of regional and religious identity, and\nanti-Western cultural sentiment.\n• 4. Consequences and Evaluation [1.5 Marks]:\n- Rising consumerism, changing youth culture, and erosion of some traditions, alongside the global diffusion of Indian\nculture through yoga, cinema, and cuisine; globalisation transforms rather than simply homogenises culture.",
