        "answer": "Comprehensive analysis: Education as agent of change; (1) Education: spread of literacy, scientific temper,\negalitarian values, gender sensitisation, social mobility, challenge to caste and patriarchal norms; (2) Mass media:\nnewspapers, radio, television, cinema, and the internet; dissemination of information, entertainment, national\nintegration, but also commodification and stereotyping; (3) Tensions: cultural lag, generation gap, conflict\nbetween traditional and modern values, moral panics over media content; (4) Positive potential: public sphere,\nsocial reform campaigns, awareness of rights; (5) Evaluation.\nStep-by-Step Marking Scheme (1.5 Marks education as agent + 1.5 Marks mass media as agent + 1.5 Marks transmission of\nnew values + 1.5 Marks tensions & evaluation):\n• 1. Education as an Agent of Change [1.5 Marks]:\n- Spreads literacy, scientific temper, egalitarian and democratic values, promotes social mobility, and challenges caste and\npatriarchal norms.\n• 2. Mass Media as an Agent [1.5 Marks]:\n- Newspapers, radio, television, cinema, and the internet disseminate information, shape public opinion, and create\nshared national and global cultural experiences.\n• 3. Transmission of New Values [1.5 Marks]:\n- Both institutions promote individualism, gender equality, consumer aspirations, and awareness of rights and\nentitlements.\n• 4. Tensions and Evaluation [1.5 Marks]:\n- They also generate cultural lag, generation gaps, conflict between traditional and modern values, and moral panics over\nmedia content; overall they are powerful but double-edged agents of cultural change.",
