        "question": "Examine the phenomenon of 'Cultural Revivalism' in India. Discuss its causes, manifestations, and sociological significance. [6\nMarks]",
        "answer": "Comprehensive examination: Definition and causes (reaction to rapid change, perceived cultural threat, identity\nassertion, colonialism and globalisation); (1) Manifestations: revival of traditional festivals and rituals, assertions\nof Hindu/Muslim/Sikh identity, promotion of indigenous knowledge systems (yoga, ayurveda), language revival\nmovements, ethnic cultural assertions; (2) Sociological significance: provides identity and belonging, resists\n\nhomogenisation, but can also become exclusionary and communal; (3) Examples: Arya Samaj, Singh Sabha,\nDeoband, Dravidian movement, North-East cultural assertions; (4) Evaluation.\nStep-by-Step Marking Scheme (1.5 Marks definition & causes + 1.5 Marks manifestations + 1.5 Marks sociological\nsignificance + 1.5 Marks examples & evaluation):\n• 1. Definition and Causes [1.5 Marks]:\n- Cultural revivalism refers to conscious efforts to reclaim, protect, and reassert traditional cultural identities and\npractices, typically arising as a reaction to rapid social change, colonialism, or globalisation.\n• 2. Manifestations [1.5 Marks]:\n- Revival of festivals and rituals, religious identity assertion, promotion of indigenous knowledge (yoga, ayurveda),\nlanguage revival, and ethnic cultural movements.\n• 3. Sociological Significance [1.5 Marks]:\n- Provides collective identity, belonging, and dignity to groups feeling threatened; resists cultural homogenisation; but can\nalso turn exclusionary, communal, or chauvinistic.\n• 4. Examples and Evaluation [1.5 Marks]:\n- Arya Samaj, Singh Sabha, Deoband, the Dravidian movement, and North-East cultural assertions; revivalism is a double-\nedged response to cultural change.",
