        "question": "Discuss the changes in 'Family, Marriage, and Kinship' as aspects of cultural change in India. Examine how values regarding\nmarriage, gender, and kinship have transformed. [6 Marks]",
        "answer": "Comprehensive examination: (1) Marriage: from parental arrangement to individual choice, love-cum-arranged\nmarriages, rise of inter-caste and inter-religious marriages, later age at marriage, rising divorce; (2) Family:\nnuclearisation, decline of patriarchal authority, dual-earner households, changing authority patterns; (3) Kinship:\nweakening of gotra exogamy in urban areas, bilateral kindred, new forms of kinship through choice; (4) Gender:\nwomen's education and employment, renegotiation of domestic roles, assertion of reproductive rights; (5)\nPersistence: endogamy, dowry, son preference; (6) Evaluation.\nStep-by-Step Marking Scheme (1.5 Marks marriage change + 1.5 Marks family change + 1.5 Marks kinship & gender change\n+ 1.5 Marks persistence & evaluation):\n• 1. Changes in Marriage [1.5 Marks]:\n- Shift from wholly arranged to choice-based and 'love-cum-arranged' marriages, rise of inter-caste and inter-religious\nunions, later marriage age, and increasing divorce and remarriage.\n• 2. Changes in Family [1.5 Marks]:\n- Nuclearisation, decline of patriarchal authority, dual-earner households, and more egalitarian decision-making, though\nthe joint family persists in modified forms.\n• 3. Kinship and Gender [1.5 Marks]:\n- Weakening of strict gotra exogamy in urban areas, greater female education and employment, renegotiation of\ndomestic roles, and assertion of reproductive and property rights.\n• 4. Persistence and Evaluation [1.5 Marks]:\n- Caste endogamy, dowry, and son preference persist despite change; cultural change in family and kinship is real but\nuneven and incomplete.",
