        "tag": "CBSE 2020 - 4/6 Marks",
        "question": "Analyse the concept of 'Cultural Change' in relation to 'Social Change'. How do the material and non-material dimensions of\nculture interact in producing social transformation? [6 Marks]",
        "answer": "Comprehensive analysis: Relationship between cultural and social change; (1) Material culture: technology, tools,\ninfrastructure, economy; Non-material culture: values, norms, beliefs, institutions; (2) Interaction: technological\nchange produces normative change (e.g. railways changing caste and family practices); normative change guides\n\ntechnology (environmental values shaping technology); (3) Cultural lag (Ogburn): uneven rates produce tension;\n(4) Examples: the impact of the printing press, mobile phones on gender seclusion, the internet on marriage; (5)\nEvaluation.\nStep-by-Step Marking Scheme (1.5 Marks relationship of cultural and social change + 1.5 Marks material vs non-material\nculture + 1.5 Marks interaction & cultural lag + 1.5 Marks examples & evaluation):\n• 1. Relationship of Cultural and Social Change [1.5 Marks]:\n- Cultural change (in values and practices) and social change (in institutions and relations) are interdependent dimensions\nof the same transformation process.\n• 2. Material versus Non-Material Culture [1.5 Marks]:\n- Material culture comprises technology, tools, infrastructure, and economic arrangements; non-material culture\ncomprises values, norms, beliefs, and institutions.\n• 3. Interaction and Cultural Lag [1.5 Marks]:\n- Technological change generates normative change (railways altering caste and purdah practices), while normative\nchange guides technological adoption; William Ogburn's cultural lag describes the tension when the two change at\ndifferent rates.\n• 4. Examples and Evaluation [1.5 Marks]:\n- The printing press, mobile phones loosening gender seclusion, and the internet transforming marriage markets illustrate\nhow material and non-material culture jointly produce social transformation.",
        "explanation": ""
