        "answer": "Comprehensive examination: Definition and scale of the Indian diaspora; (1) Transformation of host societies:\ndiffusion of Indian cuisine, festivals, yoga, spirituality, Bollywood, and contributions to economy, politics, and\nacademia; (2) Transformation of Indian culture: remittances, transnational family practices, reverse cultural\nflows, 'brain drain' and 'brain gain'; (3) Identity negotiation: hybrid identities, second-generation identity\nconflicts, multiculturalism debates; (4) Examples: Indian diaspora in the UK, USA, Gulf, Caribbean, Fiji, South\nAfrica; (5) Evaluation.\nStep-by-Step Marking Scheme (1.5 Marks definition & scale + 1.5 Marks transformation of host societies + 1.5 Marks\ntransformation of Indian culture + 1.5 Marks identity negotiation & evaluation):\n• 1. Definition and Scale [1.5 Marks]:\n- The Indian diaspora comprises over 30 million people of Indian origin living abroad, including indentured labour\ndescendants in the Caribbean and Fiji, and recent professionals in the USA, UK, and Gulf.\n• 2. Transformation of Host Societies [1.5 Marks]:\n- Diffusion of Indian cuisine, festivals (Diwali, Holi), yoga, spirituality, and Bollywood, alongside significant contributions to\nthe economy, politics, and academia of host countries.\n• 3. Transformation of Indian Culture [1.5 Marks]:\n- Remittance inflows, transnational family and marriage practices, reverse cultural flows, and the return of skills ('brain\ngain') reshape Indian society.\n• 4. Identity Negotiation and Evaluation [1.5 Marks]:\n- Diaspora communities negotiate hybrid identities and second-generation identity conflicts, and have influenced\nmulticulturalism debates in host societies.",
