        "question": "Discuss the processes of 'Sanskritisation' and 'Westernisation' as parallel processes of cultural change in India. Compare their\ndirection, agents, and consequences for Indian society. [6 Marks]",
        "answer": "Comprehensive comparison: Both coined by M.N. Srinivas; (1) Sanskritisation: internal, vertical, ritual and\n\nideological, caste-bound, rural, status-preserving; agents: lower castes aspiring upward; (2) Westernisation:\nexternal, horizontal, material and value-based, class-based, urban, modernising; agents: colonial rule, English\neducation, liberalisation; (3) Consequences: sanskritisation reinforces caste and patriarchy; westernisation\npromotes egalitarianism, individualism, and secularism; (4) Interaction: both operate simultaneously, producing\ncomplex cultural change; (5) Evaluation.\nStep-by-Step Marking Scheme (1.5 Marks Sanskritisation + 1.5 Marks Westernisation + 1.5 Marks comparison + 1.5 Marks\ninteraction & evaluation):\n• 1. Sanskritisation [1.5 Marks]:\n- An internal, vertical process of ritual emulation within the caste hierarchy, primarily rural and caste-bound, producing\nstatus change without structural transformation.\n• 2. Westernisation [1.5 Marks]:\n- An external, horizontal process of adopting Western technology, institutions, and values, primarily urban and class-\nbased, promoting modernisation, egalitarianism, and individualism.\n• 3. Comparison [1.5 Marks]:\n- Sanskritisation is conservative and status-preserving; westernisation is transformative and value-changing.\n- Sanskritisation operates within caste; westernisation cuts across caste lines through education and class.\n• 4. Interaction and Evaluation [1.5 Marks]:\n- Both processes operate simultaneously in contemporary India, producing a complex, layered cultural change in which\ntraditional emulation and modernising influences coexist and interact.",
