        "question": "\"Cultural change in India is neither linear westernisation nor simple tradition preservation, but a complex process of\nnegotiation and hybridisation.\" Evaluate this statement with reference to language, food, dress, family values, and religion. [6\nMarks]",
        "answer": "Critical evaluation: Against linear theories of change; (1) Language: Hinglish, code-switching, multilingualism,\nvernacular media growth alongside English; (2) Food: fusion cuisine, global fast food adapted to Indian tastes\n(vegetarian, regional); (3) Dress: coexistence of Western clothing with sarees, kurta, and ethnic fashion revival; (4)\nFamily values: persistence of joint family norms alongside individualism, nuclear households, and continued\nparental involvement in marriage; (5) Religion: continued religiosity alongside secular institutions, reform\nmovements, and syncretic practices; (6) Conclusion: Indian cultural change is characterised by negotiation,\nadaptation, and hybridity.",
        "explanation": "Step-by-Step Marking Scheme (1.2 Marks each for language, food, dress, family values, religion + 0.5 Mark conclusion):\n• 1. Language [1.2 Marks]:\n- Hinglish and code-switching flourish alongside the growth of vernacular media and literature; English expands without\ndisplacing regional languages.\n• 2. Food [1.2 Marks]:\n- Fusion cuisine and global fast food chains adapt to Indian tastes (vegetarian and regional menus), producing hybrid food\ncultures rather than replacement.\n• 3. Dress [1.2 Marks]:\n- Western clothing coexists with sarees, kurta, and salwar kameez, and ethnic fashion experiences revival among the\nyoung.\n• 4. Family Values [1.2 Marks]:\n- Individualism and nuclear households grow, yet parental involvement in marriage decisions and joint family norms\npersist.\n• 5. Religion [1.2 Marks]:\n- Religiosity remains strong alongside secular institutions, reform movements, and syncretic practices.\n• 6. Conclusion [0.5 Mark]:\n- Indian cultural change is a process of negotiation and hybridisation, not linear westernisation or passive preservation of\ntradition."
