      {
        "id": 47,
        "type": "LA",
        "tag": "CBSE 2020 - 4/6 Marks",
        "question": "Analyse the impact of globalisation on 'Rural Society' in India. Examine changes in agriculture, rural employment, migration,\nand rural culture. [6 Marks]",
        "answer": "Comprehensive analysis: Rural transformation under globalisation; (1) Agriculture: commercialisation, contract\nfarming, export-oriented crops, mechanisation, input cost inflation, farmer distress; (2) Rural employment:\ndecline of traditional crafts and artisans, growth of non-farm employment, MNREGA; (3) Migration: rural-urban\nand interstate migration, remittances, feminisation of agriculture; (4) Rural culture: spread of television, mobile\nphones, consumer goods, changing aspirations, education; (5) Consequences: agrarian crisis, inequality, cultural\nchange; (6) Evaluation.\nStep-by-Step Marking Scheme (1.5 Marks agriculture + 1.5 Marks employment & migration + 1.5 Marks culture + 1.5 Marks\nconsequences & evaluation):\n• 1. Agriculture [1.5 Marks]:\n- Commercialisation, contract farming, export-oriented crops, mechanisation, and rising input costs, alongside falling\nreturns and farmer distress.\n• 2. Employment and Migration [1.5 Marks]:\n- Decline of traditional crafts and artisanal employment, growth of non-farm work, large-scale rural-urban and interstate\nmigration, remittance inflows, and the feminisation of agriculture.\n• 3. Rural Culture [1.5 Marks]:\n- Spread of television, mobile phones, consumer goods, and modern education transformed rural aspirations, gender\nrelations, and leisure.\n• 4. Consequences and Evaluation [1.5 Marks]:\n- An agrarian crisis combined with rising inequality and cultural change; globalisation has been more disruptive than\nbeneficial for much of rural India.",
        "explanation": ""
      },
      {
        "id": 48,
        "type": "LA",
        "tag": "CBSE 2019 - 4/6 Marks",
        "question": "Examine the concept of 'Globalisation' from a sociological perspective. How does it differ from the purely economic\nunderstanding, and what are its implications for the study of society? [6 Marks]",
        "answer": "Comprehensive examination: Sociological vs economic understanding; (1) Economic understanding: flows of\ncapital, trade, and investment, GDP growth; (2) Sociological understanding: transformation of social relations,\nculture, identity, work, family, community, and inequality; (3) Key concepts: time-space compression (Harvey),\ndisembedding (Giddens), glocalisation, hybridisation; (4) Implications for sociology: the need to study\ntransnational social fields, diaspora, global inequality, and the local responses to global forces; (5) Evaluation.\nStep-by-Step Marking Scheme (1.5 Marks economic vs sociological understanding + 1.5 Marks key sociological concepts +\n1.5 Marks implications for the study of society + 1.5 Marks evaluation):\n• 1. Economic versus Sociological Understanding [1.5 Marks]:\n- The economic view focuses on trade, capital flows, investment, and growth; the sociological view examines how\nglobalisation transforms social relations, culture, identity, work, and community.\n• 2. Key Sociological Concepts [1.5 Marks]:\n- Time-space compression (David Harvey), disembedding of social relations (Anthony Giddens), glocalisation, cultural\nhybridisation, and transnationalism.\n• 3. Implications for the Study of Society [1.5 Marks]:\n- Sociology must study transnational social fields, diaspora communities, global inequality, and the ways local\ncommunities negotiate, resist, and adapt to global forces.\n• 4. Evaluation [1.5 Marks]:\n- A sociological perspective reveals that globalisation is not merely an economic phenomenon but a total social\n\ntransformation with uneven and contested consequences.",
        "explanation": ""
      },
      {
        "id": 49,
        "type": "LA",
        "tag": "CBSE 2018 - 4/6 Marks",
        "question": "Discuss the role of 'Transnational Corporations' in the Indian economy. Examine their impact on employment, technology,\nconsumer culture, and domestic industry. [6 Marks]",
        "answer": "Comprehensive examination: Definition and growth of TNCs in India; (1) Employment: creation of direct and\nindirect jobs, but also displacement of traditional employment and informalisation; (2) Technology: transfer of\ntechnology, management practices, and integration into global value chains; (3) Consumer culture: branding,\nadvertising, malls, e-commerce, changing lifestyles; (4) Domestic industry: competition forcing efficiency, but also\ndisplacement of small producers and artisans; (5) Consequences: growth and inequality; (6) Evaluation.\nStep-by-Step Marking Scheme (1.5 Marks employment impact + 1.5 Marks technology transfer + 1.5 Marks consumer\nculture + 1.5 Marks domestic industry & evaluation):\n• 1. Employment Impact [1.5 Marks]:\n- TNCs create direct and indirect employment and support ancillary industries, but also displace traditional occupations\nand expand informal, contract-based work.\n• 2. Technology Transfer [1.5 Marks]:\n- They introduce advanced technology, management practices, and quality standards, integrating Indian firms into global\nvalue chains.\n• 3. Consumer Culture [1.5 Marks]:\n- Through branding, advertising, malls, and e-commerce, TNCs shape consumer aspirations, lifestyles, and identities.\n• 4. Domestic Industry and Evaluation [1.5 Marks]:\n- They force domestic firms to improve efficiency, but can also marginalise small producers and artisans; their net impact\nis growth-enhancing but structurally unequal.",
        "explanation": ""
      },
      {
        "id": 50,
        "type": "LA",
        "tag": "CBSE 2017 - 4/6 Marks",
        "question": "\"Globalisation is a double-edged sword: it creates opportunities for some while exacerbating vulnerabilities for others.\"\nCritically evaluate this statement with reference to India's experience. [6 Marks]",
        "answer": "Critical evaluation: The contradictory character of globalisation; (1) Opportunities: economic growth, IT and\nservices employment, consumer choice, technology access, global visibility of Indian culture, diaspora networks;\n(2) Vulnerabilities: agrarian distress, displacement of artisans and Adivasis, informalisation and job insecurity,\nwidening inequality, regional disparity, cultural homogenisation, environmental degradation; (3) Group-specific\nimpacts: middle class vs workers; urban vs rural; men vs women; forward vs backward castes; (4) Policy\nimplications: inclusive growth, social protection, skill development, regulation of corporate power; (5)\nConclusion.\nStep-by-Step Marking Scheme (1.5 Marks opportunities + 2 Marks vulnerabilities + 1.5 Marks group-specific impacts + 1\nMark policy implications & conclusion):\n• 1. Opportunities [1.5 Marks]:\n- Rapid economic growth, IT and services employment, greater consumer choice, technology access, global visibility of\nIndian culture, and strong diaspora networks.\n• 2. Vulnerabilities [2 Marks]:\n- Agrarian distress and farmer indebtedness; displacement of artisans, weavers, and Adivasis; informalisation and job\ninsecurity; widening income and regional inequality; cultural homogenisation; and environmental degradation.\n• 3. Group-Specific Impacts [1.5 Marks]:\n- The urban educated middle class gained most, while workers, farmers, women in export industries, and backward castes\nfaced disproportionate costs; impacts are structured by class, region, gender, and caste.\n• 4. Policy Implications and Conclusion [1 Mark]:\n- Inclusive growth, social protection, skill development, and regulation of corporate power are essential; globalisation's\n\noutcomes are politically shaped, not automatically determined.",
        "explanation": ""
      }
