        "answer": "Comprehensive examination: Context of rural unemployment and poverty; (1) Earlier programmes: Community\nDevelopment Programme (1952), National Rural Employment Programme (1980), Jawahar Rozgar Yojana (1989);\n(2) MGNREGA (2005): rights-based framework, 100 days guarantee, wage employment, asset creation, social\naudit; (3) Other initiatives: National Rural Livelihood Mission (NRLM), Deen Dayal Upadhyaya Grameen Kaushalya\nYojana, Pradhan Mantri Awas Yojana (Gramin), Swachh Bharat Mission (Gramin); (4) Impact: livelihood security,\nreduced distress migration, women's empowerment, rural infrastructure; (5) Challenges: fund delays, low wage\nrates, implementation gaps; (6) Evaluation.\nStep-by-Step Marking Scheme (1.5 Marks context & earlier programmes + 1.5 Marks MGNREGA + 1.5 Marks other\ninitiatives + 1.5 Marks impact, challenges & evaluation):\n• 1. Context and Earlier Programmes [1.5 Marks]:\n- Chronic rural unemployment and poverty prompted wage employment programmes: the Community Development\nProgramme (1952), National Rural Employment Programme (1980), and Jawahar Rozgar Yojana (1989).\n• 2. MGNREGA (2005) [1.5 Marks]:\n- A rights-based programme guaranteeing 100 days of unskilled manual wage employment per rural household, with\nprovisions for unemployment allowance, worksite facilities, and social audit.\n• 3. Other Initiatives [1.5 Marks]:\n- National Rural Livelihood Mission (self-help groups), skill development programmes, rural housing (PMAY-Gramin), and\nrural sanitation (SBM-Gramin).\n• 4. Impact, Challenges, and Evaluation [1.5 Marks]:\n- Improved livelihood security, reduced distress migration, empowered women, and created rural assets; challenges\ninclude delayed wage payments, low wage rates, and implementation gaps.",
