        "answer": "Comprehensive analysis: Causes of agrarian distress; (1) Structural: fragmentation of landholdings,\nmarginalisation, dependence on rainfall, declining public investment; (2) Economic: rising input costs, falling crop\nprices, indebtedness, withdrawal of institutional credit, exposure to global markets; (3) Policy: inadequate MSP\nimplementation, WTO constraints, reduction in fertiliser subsidies; (4) Social: farmer suicides, distress migration,\nfeminisation of agriculture; (5) Measures: irrigation, crop insurance, MSP guarantee, institutional credit,\ndiversification, agro-processing, land consolidation, and non-farm employment; (6) Evaluation.\nStep-by-Step Marking Scheme (1.5 Marks structural causes + 1.5 Marks economic & policy causes + 1.5 Marks social\nconsequences + 1.5 Marks measures & evaluation):\n• 1. Structural Causes [1.5 Marks]:\n- Fragmentation and marginalisation of landholdings, continued dependence on monsoon, and declining public\ninvestment in agriculture.\n• 2. Economic and Policy Causes [1.5 Marks]:\n- Rising input costs, falling crop prices, indebtedness, withdrawal of institutional credit, exposure to global price volatility,\nand inadequate MSP implementation under WTO constraints.\n• 3. Social Consequences [1.5 Marks]:\n- Farmer suicides, distress migration, growing rural indebtedness, and the feminisation of agriculture as men migrate.\n• 4. Measures and Evaluation [1.5 Marks]:\n- Expand irrigation and crop insurance, guarantee MSP, strengthen institutional credit and cooperatives, promote crop\ndiversification and agro-processing, consolidate holdings, and generate non-farm rural employment.",
