        "question": "Examine the significance of 'Panchayati Raj' in rural development and social change. Discuss the provisions of the 73rd\nConstitutional Amendment and its impact on rural governance and social relations. [6 Marks]",
        "answer": "Comprehensive examination: Decentralised governance; (1) Historical background: Balwant Rai Mehta\nCommittee (1957), Ashok Mehta Committee (1978), L.M. Singhvi Committee; (2) 73rd Amendment (1992): three-\ntier structure, mandatory elections, reservations for SCs/STs and one-third for women, State Election and Finance\nCommissions, 29 subjects in the Eleventh Schedule; (3) Impact: political participation of women and marginalised\ngroups, grassroots democracy, local planning; (4) Limitations: inadequate funds, state control, elite capture, low\ncapacity; (5) Evaluation.\nStep-by-Step Marking Scheme (1.5 Marks historical background + 2 Marks 73rd Amendment provisions + 1.5 Marks impact\n+ 1 Mark limitations & evaluation):\n• 1. Historical Background [1.5 Marks]:\n- The Balwant Rai Mehta Committee (1957) recommended democratic decentralisation; the Ashok Mehta (1978) and L.M.\nSinghvi committees further developed the idea, leading to the 73rd Amendment.\n• 2. Provisions of the 73rd Amendment (1992) [2 Marks]:\n- Three-tier structure: Gram Panchayat, Panchayat Samiti, and Zila Parishad.\n- Mandatory elections every five years with reservations for SCs and STs and not less than one-third of seats for women.\n- State Election Commissions and State Finance Commissions; devolution of 29 subjects listed in the Eleventh Schedule.\n• 3. Impact [1.5 Marks]:\n- Enhanced political participation of women and marginalised communities, strengthened grassroots democracy, and\nimproved local accountability and planning.\n• 4. Limitations and Evaluation [1 Mark]:\n- Inadequate financial devolution, state control, elite capture, and limited capacity of elected members; panchayati raj is a\nsignificant but incomplete democratic transformation.",
        "explanation": ""
