        "question": "\"Rural development in India has shifted from land reform and community development to employment guarantees and\nlivelihood promotion.\" Evaluate this statement, discussing the changing strategies of rural development since Independence. [6\nMarks]",
        "answer": "Critical evaluation: Changing rural development paradigms; (1) Phase 1 (1950s–60s): land reforms, abolition of\nzamindari, Community Development Programme, institution building; (2) Phase 2 (1960s–70s): Green Revolution,\ntechnology-led growth, high-yielding varieties; (3) Phase 3 (1970s–80s): target group approaches, IRDP, small\nfarmer development, anti-poverty programmes; (4) Phase 4 (1990s onwards): liberalisation, declining public\ninvestment, wage employment programmes (MGNREGA), self-help groups, livelihood mission; (5) Evaluation:\nshift from redistribution to growth, then to social protection and livelihoods.\nStep-by-Step Marking Scheme (1.5 Marks Phase 1 + 1.5 Marks Phase 2 + 1.5 Marks Phase 3 + 1.5 Marks Phase 4 &\nevaluation):\n• 1. Phase 1 (1950s–60s) [1.5 Marks]:\n- Land reforms, abolition of zamindari, the Community Development Programme (1952), and institution building\n(cooperatives, panchayati raj).\n• 2. Phase 2 (1960s–70s) [1.5 Marks]:\n- The Green Revolution, technology-led agricultural growth, HYV seeds, irrigation, and mechanisation.\n• 3. Phase 3 (1970s–80s) [1.5 Marks]:\n- Target group approaches — Integrated Rural Development Programme (IRDP), small farmer development, and anti-\npoverty programmes.\n• 4. Phase 4 (1990s onwards) and Evaluation [1.5 Marks]:\n- Liberalisation with declining public investment, followed by wage employment guarantees (MGNREGA), self-help\ngroups, and livelihood missions; rural development strategy has shifted from land redistribution to growth, then to social\nprotection and livelihood promotion.",
