        "answer": "Comprehensive examination: (1) Caste: weakening of hereditary occupations, but persistence of caste in\nindustrial recruitment and informal networks; (2) Class: emergence of industrial bourgeoisie, middle class, and\nworking class; class consciousness and trade unionism; (3) Family: nuclearisation, migration, changing authority\npatterns, dual-earner households; (4) Gender: women's factory employment and new economic roles, but also\nthe double burden, wage discrimination, and sexual harassment; (5) Other consequences: urbanisation,\nsecularisation, individualism; (6) Evaluation.\nStep-by-Step Marking Scheme (1.5 Marks caste & class + 1.5 Marks family + 1.5 Marks gender + 1.5 Marks other\nconsequences & evaluation):\n• 1. Caste and Class [1.5 Marks]:\n- Industrialisation weakened caste-based hereditary occupations but caste persists in recruitment and informal networks;\nit produced an industrial bourgeoisie, middle class, and working class, along with class consciousness and unionism.\n• 2. Family [1.5 Marks]:\n- Nuclearisation of families, migration away from joint households, changing patriarchal authority, and the emergence of\ndual-earner households.\n• 3. Gender [1.5 Marks]:\n- Women's factory and office employment created new economic roles and autonomy, but the double burden of work,\nwage discrimination, and workplace harassment persist.\n• 4. Other Consequences and Evaluation [1.5 Marks]:\n- Urbanisation, secularisation, and individualism; industrialisation has transformed Indian society profoundly but\nunevenly, often preserving older inequalities in new forms.",
