        "answer": "Comprehensive examination: Definition and magnitude; (1) Causes: poverty, illiteracy, debt bondage, demand for\ncheap labour, failure of education, migration, family tradition; (2) Consequences: loss of education and childhood,\nhealth damage and stunted growth, exploitation and abuse, intergenerational transmission of poverty; (3)\nLegislative measures: Child Labour (Prohibition and Regulation) Act 1986, Juvenile Justice Act, Right to Education\nAct 2009, and the Child Labour (Prohibition and Regulation) Amendment Act 2016 banning employment of\nchildren below 14; (4) Policy measures: National Child Labour Project, rehabilitation and schooling, midday meals;\n(5) Evaluation.\nStep-by-Step Marking Scheme (1.5 Marks causes + 1.5 Marks consequences + 1.5 Marks legislative measures + 1.5 Marks\npolicy measures & evaluation):\n• 1. Causes [1.5 Marks]:\n- Poverty, illiteracy, debt bondage, demand for cheap labour, lack of access to schooling, migration, and family\noccupational tradition.\n• 2. Consequences [1.5 Marks]:\n- Loss of education and childhood, health damage and stunted growth, exploitation and abuse, and the intergenerational\ntransmission of poverty.\n• 3. Legislative Measures [1.5 Marks]:\n- Child Labour (Prohibition and Regulation) Act 1986, the Right to Education Act 2009, the Juvenile Justice Act, and the\n2016 amendment prohibiting employment of children below 14 in all occupations.\n• 4. Policy Measures and Evaluation [1.5 Marks]:\n- National Child Labour Project, rehabilitation and bridge education, and midday meals; enforcement remains weak, and\nelimination requires poverty alleviation and universal education.",
