        "answer": "Critical evaluation: Dual character of Indian industrialisation; (1) Modernisation: technological progress, economic\ngrowth, urbanisation, occupational mobility, women's employment, rise of a middle class; (2) New inequalities:\nclass concentration of wealth, informalisation and job insecurity, regional concentration in a few states, gendered\nwage discrimination and the double burden, and the digital divide; (3) Formal-informal divide: a minority in\nprotected formal employment and a vast majority in insecure informal work; (4) Consequences: social\npolarisation and uneven development; (5) Conclusion.\nStep-by-Step Marking Scheme (1.5 Marks modernisation + 1.5 Marks class & regional inequality + 1.5 Marks gender &\nformal-informal divide + 1.5 Marks conclusion & policy implications):\n• 1. Modernisation [1.5 Marks]:\n- Technological progress, sustained economic growth, urbanisation, occupational mobility, women's employment, and the\nrise of a large urban middle class.\n• 2. Class and Regional Inequality [1.5 Marks]:\n- Concentration of industrial wealth among a small capitalist and professional class, and the concentration of industry in a\nfew advanced states, widening regional disparity.\n• 3. Gender and the Formal-Informal Divide [1.5 Marks]:\n- Gendered wage discrimination, occupational segregation, and the double burden for women; a minority enjoys\nprotected formal employment while the vast majority works in insecure, unregulated informal employment.\n• 4. Conclusion and Policy Implications [1.5 Marks]:\n- Industrialisation has modernised India but generated new forms of inequality; inclusive growth requires labour\nprotection, skill development, regional dispersal, and gender-equitable employment policy.",
