        "answer": "Comprehensive examination: (1) Growth of transnational media: entry of CNN, BBC, Star TV, and global digital\nplatforms; (2) Consequences: expansion of choice, professionalisation, technological upgrading, and 24×7 news;\n(3) Cultural imperialism: domination of Western content and formats, threat to local languages and cultures,\nhomogenisation of tastes; (4) Indian response: growth of strong Hindi and regional-language channels, indigenous\ncontent formats, Indian film and television industries going global; (5) Tensions: global formats versus local\nidentities; (6) Evaluation.\nStep-by-Step Marking Scheme (1.5 Marks growth of transnational media + 1.5 Marks cultural imperialism + 1.5 Marks\nIndian response + 1.5 Marks tensions & evaluation):\n• 1. Growth of Transnational Media [1.5 Marks]:\n- The entry of CNN, BBC, Star TV, and global digital platforms expanded choice, professionalised Indian broadcasting, and\nenabled 24×7 news.\n• 2. Cultural Imperialism [1.5 Marks]:\n- The domination of Western content, formats, and ownership raises fears of cultural homogenisation and threats to local\nlanguages, cultures, and values.\n• 3. Indian Response [1.5 Marks]:\n- The growth of strong Hindi and regional-language channels, indigenous content formats, and the global expansion of\nIndian film and television industries.\n• 4. Tensions and Evaluation [1.5 Marks]:\n- A continuing tension between global formats and local identities; Indian media have both adapted to and resisted\nglobalisation, producing hybrid cultural forms.",
