        "answer": "Comprehensive examination: (1) Growth: cheap mobile data, smartphone penetration, platforms like WhatsApp,\nFacebook, X, Instagram, YouTube; (2) Political role: election campaigning, citizen mobilisation, digital activism,\naccountability of leaders; (3) Social role: community formation, support networks, awareness campaigns, disaster\nresponse; (4) Cultural role: new forms of expression, influencer culture, digital creativity; (5) Dangers:\nmisinformation and fake news, echo chambers, cyberbullying, privacy violations, hate speech, mob violence; (6)\nEvaluation.\nStep-by-Step Marking Scheme (1.5 Marks growth + 1.5 Marks political & social role + 1.5 Marks cultural role + 1.5 Marks\ndangers & evaluation):\n• 1. Growth [1.5 Marks]:\n- Cheap mobile data, widespread smartphone penetration, and platforms such as WhatsApp, Facebook, X, Instagram, and\nYouTube have made India one of the world's largest social media markets.\n• 2. Political and Social Role [1.5 Marks]:\n- Election campaigning, citizen mobilisation, digital activism, accountability of leaders, community formation, support\nnetworks, and disaster response.\n• 3. Cultural Role [1.5 Marks]:\n- New forms of cultural expression, digital creativity, influencer culture, and the emergence of vernacular online publics.\n• 4. Dangers and Evaluation [1.5 Marks]:\n- Misinformation and fake news, echo chambers, cyberbullying, privacy violations, hate speech, and mob violence; social\nmedia democratise communication but require digital literacy and regulation.",
        "explanation": ""
