        "tag": "CBSE 2022 - 4/6 Marks",
        "question": "Analyse the role of mass media in 'Social Change and Development' in India. Examine media as an instrument of education,\nsocial reform, and national integration. [6 Marks]",
        "answer": "Comprehensive analysis: (1) Education: distance education, Gyan Darshan and Gyan Vani, educational television\nand digital learning; (2) Social reform: campaigns on health, sanitation, immunisation, female foeticide, dowry,\nenvironment, and gender equality; (3) Development communication: agricultural information, Kheda and SITE\nexperiments, community radio for rural development; (4) National integration: exposure to diverse languages and\ncultures, shared national public sphere; (5) Limitations: reach of the digital divide, urban bias, commercialisation\nof developmental content; (6) Evaluation.\nStep-by-Step Marking Scheme (1.5 Marks education + 1.5 Marks social reform + 1.5 Marks development communication &\nnational integration + 1.5 Marks limitations & evaluation):\n• 1. Education [1.5 Marks]:\n- Distance education channels (Gyan Darshan, Gyan Vani), educational television, and digital learning platforms have\nexpanded access to education beyond formal institutions.\n• 2. Social Reform [1.5 Marks]:\n- Campaigns on health, sanitation, immunisation, female foeticide, dowry, environment, and gender equality have raised\npublic awareness and changed attitudes.\n• 3. Development Communication and National Integration [1.5 Marks]:\n- Agricultural information, the SITE/Kheda experiments, and community radio support rural development; exposure to\ndiverse languages and cultures fosters national integration.\n• 4. Limitations and Evaluation [1.5 Marks]:\n- The digital divide, urban bias, and the commercialisation of content limit media's developmental role; nonetheless,\nmedia remain a powerful instrument of education and reform.",
        "explanation": ""
