        "tag": "CBSE 2019 - 4/6 Marks",
        "question": "Examine the role of the mass media in the formation of 'Public Opinion'. Discuss the concepts of agenda-setting and\ngatekeeping, and evaluate the limits of media influence. [6 Marks]",
        "answer": "Comprehensive examination: (1) Public opinion formation: media provide information, frames, and\ninterpretations shaping public understanding; (2) Agenda-setting: media influence which issues are considered\nimportant through prominence and repetition; (3) Gatekeeping: editors and media personnel select and frame\nnews, determining what reaches the public; (4) Other influences: interpersonal communication, family, caste,\ncommunity, personal experience, and ideology mediate media effects; (5) Limits: selective exposure, selective\nperception, active audiences, and media literacy; (6) Evaluation.\nStep-by-Step Marking Scheme (1.5 Marks public opinion formation + 1.5 Marks agenda-setting + 1.5 Marks gatekeeping +\n1.5 Marks limits & evaluation):\n• 1. Public Opinion Formation [1.5 Marks]:\n- The media provide the information, frames, and interpretations through which citizens understand public issues, playing\na central role in the formation of public opinion.\n• 2. Agenda-Setting [1.5 Marks]:\n- By the prominence and repetition they give to issues, the media influence what the public considers important, even if\nthey do not dictate what to think.\n• 3. Gatekeeping [1.5 Marks]:\n- Editors and media personnel select, filter, and frame news, determining which events become news and from what\nperspective they are presented.\n• 4. Limits and Evaluation [1.5 Marks]:\n- Interpersonal communication, family, caste, community, personal experience, selective exposure and perception, and\nactive audiences limit media influence; media are powerful but not all-powerful.",
        "explanation": ""
