        "question": "\"The mass media are both a mirror and a maker of society.\" Critically evaluate this statement with reference to the Indian\nexperience. [6 Marks]",
        "answer": "Critical evaluation: Dual role of media; (1) Media as mirror: reflecting society's diversity, conflicts, aspirations,\nlanguages, and cultures; news, films, and serials depict social realities; (2) Media as maker: shaping opinion,\nsetting agendas, constructing identities, promoting consumerism, and normalising values; media campaigns\nchange behaviour; (3) Indian experience: media's role in the freedom struggle, development communication,\ntelevision's social impact, social media activism, but also sensationalism and misinformation; (4) Tension: media\nreflect social power structures while also transforming them; (5) Conclusion.\nStep-by-Step Marking Scheme (1.5 Marks media as mirror + 1.5 Marks media as maker + 1.5 Marks Indian experience + 1.5\nMarks conclusion & critical evaluation):\n• 1. Media as Mirror [1.5 Marks]:\n- Media reflect society's diversity, conflicts, aspirations, languages, and cultures; news, films, and serials depict social\nrealities and give visibility to different groups.\n• 2. Media as Maker [1.5 Marks]:\n- Media shape public opinion, set agendas, construct identities, promote consumerism, and normalise values; campaigns\nand content can change behaviour and attitudes.\n• 3. Indian Experience [1.5 Marks]:\n- The nationalist press, development communication, television's social impact, and social media activism show media's\nconstructive power, while sensationalism, paid news, and misinformation reveal its distortions.\n• 4. Conclusion and Critical Evaluation [1.5 Marks]:\n- Media both reflect and reshape society; because they are embedded in social power structures, an ethical, plural, and\naccessible media system is essential for a democratic society.",
