        "answer": "Comprehensive examination: Context of ecological degradation and displacement; (1) Chipko movement (1973):\nforest conservation, tree-embracing, women's participation, ban on commercial felling; (2) Narmada Bachao\n\nAndolan (1980s): opposition to large dams, displacement of adivasis, demands for rehabilitation; (3) Silent Valley\nmovement (1970s–80s): protection of tropical evergreen forest and biodiversity from a hydroelectric project; (4)\nMethods: non-violent satyagraha, petitions, marches, public interest litigation; (5) Significance: ecological\nawareness, forest rights, influence on policy, and the linking of environment with livelihood and justice; (6)\nEvaluation.\nStep-by-Step Marking Scheme (1.5 Marks Chipko + 1.5 Marks Narmada Bachao Andolan + 1.5 Marks Silent Valley + 1.5\nMarks methods, significance & evaluation):\n• 1. Chipko Movement [1.5 Marks]:\n- Beginning in 1973 in the Garhwal Himalaya, villagers, especially women, embraced trees to prevent commercial logging,\nlinking forest conservation with livelihood rights.\n• 2. Narmada Bachao Andolan [1.5 Marks]:\n- Led by Medha Patkar, it opposed large dams on the Narmada, demanding the rehabilitation of displaced adivasis and\npeasants and challenging the dominant development model.\n• 3. Silent Valley Movement [1.5 Marks]:\n- A successful campaign to protect Kerala's Silent Valley, a rare tropical evergreen forest, from a hydroelectric project,\nhighlighting biodiversity conservation.\n• 4. Methods, Significance, and Evaluation [1.5 Marks]:\n- Non-violent satyagraha, petitions, marches, and public interest litigation; these movements created ecological\nconsciousness, influenced policy, and linked environmental protection with social justice.",
