        "question": "Analyse the 'Dalit Movement' in India. Discuss its historical phases, major struggles, achievements, and the challenges it\ncontinues to face. [6 Marks]",
        "answer": "Comprehensive analysis: Historical roots and phases; (1) Early phase: Phule, Ambedkar, Periyar, temple entry\nsatyagrahas (Mahad 1927, Kalaram), Depressed Classes movement; (2) Post-independence phase: constitutional\nsafeguards, reservations, assertion of Dalit identity and literature; (3) Contemporary phase: assertion of Dalit\nidentity, demands for land and dignity, opposition to atrocities; (4) Achievements: abolition of untouchability,\nconstitutional equality, reservations, political representation; (5) Challenges: persistent caste discrimination,\natrocities, economic deprivation, and the gap between legal equality and social reality; (6) Evaluation.\nStep-by-Step Marking Scheme (1.5 Marks early phase + 1.5 Marks post-independence & contemporary phases + 1.5 Marks\nachievements + 1.5 Marks challenges & evaluation):\n• 1. Early Phase [1.5 Marks]:\n- The anti-caste work of Phule, Ambedkar, and Periyar, the Mahad satyagraha (1927) and Kalaram temple entry march,\nand the organisation of the Depressed Classes.\n• 2. Post-Independence and Contemporary Phases [1.5 Marks]:\n- Constitutional safeguards and reservations after 1947, followed by the assertion of Dalit identity, Dalit literature, and\ndemands for land, dignity, and protection from atrocities.\n• 3. Achievements [1.5 Marks]:\n- Constitutional abolition of untouchability, guarantees of equality, reservations in education and employment, and\ngrowing political representation and social assertion.\n• 4. Challenges and Evaluation [1.5 Marks]:\n- Persistent caste discrimination, atrocities, economic deprivation, and the gap between formal legal equality and\nsubstantive social equality; the movement continues to struggle for dignity and justice.",
