        "question": "Examine the 'Peasant Movements' in colonial and post-independence India. Discuss the causes, notable movements, and their\nconsequences. [6 Marks]",
        "answer": "Comprehensive examination: Causes of peasant mobilisation; (1) Colonial context: high revenue, zamindari and\njagirdari exploitation, commercialisation, indebtedness; (2) Notable movements: Indigo Revolt (1859–60), Deccan\nRiots (1875), Champaran satyagraha (1917), Kheda (1918), Moplah Rebellion (1921), Bardoli Satyagraha (1928),\nTebhaga (1946), Telangana (1946–51); (3) Methods: petitions, satyagraha, no-tax campaigns, and armed struggle;\n(4) Consequences: tenancy reforms, land reforms, political consciousness, and the incorporation of peasant\ndemands into the nationalist movement; (5) Post-independence: land reforms and the decline of large-scale\npeasant movements, replaced by farmers' movements; (6) Evaluation.\nStep-by-Step Marking Scheme (1.5 Marks causes + 2 Marks notable movements + 1.5 Marks consequences + 1 Mark\nevaluation):\n• 1. Causes [1.5 Marks]:\n- High land revenue and rents, zamindari and jagirdari exploitation, commercialisation of agriculture, indebtedness, and\ninsecure tenancy.\n• 2. Notable Movements [2 Marks]:\n- Indigo Revolt (1859–60), Deccan Riots (1875), Champaran and Kheda satyagrahas (1917–18), Moplah Rebellion (1921),\nBardoli Satyagraha (1928), Tebhaga (1946), and the Telangana struggle (1946–51).\n• 3. Consequences [1.5 Marks]:\n- Tenancy and land reforms, heightened political consciousness, and the incorporation of peasant grievances into the\nanti-colonial nationalist movement.\n• 4. Evaluation [1 Mark]:\n- Peasant movements shaped both colonial policy and the agrarian agenda of independent India, though land inequality\nand agrarian distress persist.",
