        "question": "Discuss the 'Right to Information Movement' in India. Examine its origins, methods, achievements, and its significance for\ndemocracy. [6 Marks]",
        "answer": "Comprehensive examination: Origins of the RTI movement; (1) Origins: grassroots struggles in Rajasthan led by\nthe Mazdoor Kisan Shakti Sangathan (MKSS) demanding access to official records of public works; (2) Methods:\njan sunwai (public hearings), protests, and campaigns for transparency; (3) Achievements: state-level RTI laws in\nseveral states and the national RTI Act 2005 guaranteeing citizens the right to information from public authorities;\n(4) Significance: transparency and accountability in governance, empowerment of citizens, exposure of\ncorruption, and the strengthening of participatory democracy; (5) Challenges: weak implementation, lack of\npenalties, bureaucratic resistance, and threats to activists; (6) Evaluation.\nStep-by-Step Marking Scheme (1.5 Marks origins + 1.5 Marks methods & achievements + 1.5 Marks significance + 1.5\nMarks challenges & evaluation):\n• 1. Origins [1.5 Marks]:\n- The movement grew from grassroots struggles in Rajasthan led by the Mazdoor Kisan Shakti Sangathan, which\ndemanded access to official records of public works to expose corruption.\n• 2. Methods and Achievements [1.5 Marks]:\n- Jan sunwai (public hearings), protests, and campaigns led to state RTI laws and finally the Right to Information Act 2005.\n• 3. Significance [1.5 Marks]:\n- It institutionalised transparency and accountability, empowered citizens, exposed corruption, and strengthened\nparticipatory democracy.\n• 4. Challenges and Evaluation [1.5 Marks]:\n- Weak implementation, inadequate penalties, bureaucratic resistance, and threats to information activists; the RTI is a\nlandmark democratic reform whose effectiveness depends on vigilant citizen use.",
