        "question": "Analyse the role of 'Class, Caste, and Gender' in the emergence of social movements in India. Discuss how these structural\nlocations shape movement mobilisation. [6 Marks]",
        "answer": "Comprehensive analysis: Structural bases of mobilisation; (1) Class: exploitation, land, wages, and economic\ninequality generate peasant, worker, and farmer movements; (2) Caste: untouchability, discrimination, and status\nhierarchies generate Dalit and lower-caste movements, often intersecting with class; (3) Gender: patriarchy,\nviolence, and discrimination generate women's movements, which themselves are stratified by caste and class;\n(4) Intersectionality: movements are shaped by overlapping identities, producing different agendas for different\ngroups; (5) Consequences: both fragmentation and broadening of the movement agenda; (6) Evaluation.\nStep-by-Step Marking Scheme (1.5 Marks class + 1.5 Marks caste + 1.5 Marks gender + 1.5 Marks intersectionality &\nevaluation):\n• 1. Class [1.5 Marks]:\n- Economic exploitation, land alienation, and wage inequality generate peasant, working-class, and farmers' movements\nseeking material redistribution.\n• 2. Caste [1.5 Marks]:\n- Untouchability, discrimination, and status hierarchies generate Dalit and lower-caste movements for dignity, rights, and\nreservations, often intersecting with class position.\n• 3. Gender [1.5 Marks]:\n- Patriarchy, violence, and discrimination generate women's movements, which are themselves stratified by caste, class,\n\nand region.\n• 4. Intersectionality and Evaluation [1.5 Marks]:\n- Overlapping identities produce different agendas for different groups, both fragmenting and broadening the movement\nlandscape; understanding mobilisation requires attention to the intersection of class, caste, and gender.",
