        "tag": "CBSE 2018 - 4/6 Marks",
        "question": "Examine the theories that explain the emergence of social movements. Discuss structural strain, relative deprivation, resource\nmobilisation, and political process perspectives. [6 Marks]",
        "answer": "Comprehensive examination: Theories of social movements; (1) Structural strain: tensions and contradictions in\nsociety create conditions for mobilisation; (2) Relative deprivation: perceived gap between expectations and\nreality relative to reference groups generates discontent; (3) Resource mobilisation: movements require\nresources, organisation, leadership, and access to institutions, not merely grievances; (4) Political process:\npolitical opportunities, state response, and elite alliances shape movement emergence and success; (5)\nEvaluation: each theory captures part of the phenomenon, and a comprehensive account requires integrating\nstructure, grievance, resources, and political context.\nStep-by-Step Marking Scheme (1.5 Marks structural strain + 1.5 Marks relative deprivation + 1.5 Marks resource\nmobilisation + 1.5 Marks political process & evaluation):\n• 1. Structural Strain [1.5 Marks]:\n- Social tensions, inequalities, and contradictions in the social structure create conditions of discontent that can produce\ncollective mobilisation.\n• 2. Relative Deprivation [1.5 Marks]:\n- Movements arise when people perceive a gap between what they have and what they believe they deserve relative to\nothers, generating frustration and grievance.\n• 3. Resource Mobilisation [1.5 Marks]:\n- Grievances alone are insufficient; successful movements require resources, organisation, leadership, and access to\nnetworks and institutions to mobilise effectively.\n• 4. Political Process and Evaluation [1.5 Marks]:\n- Political opportunities, state responses, and elite alliances shape whether movements emerge and succeed; a\ncomprehensive explanation integrates structure, grievance, resources, and political context.",
