        "question": "\"Social movements have been the conscience of Indian democracy.\" Critically evaluate this statement with reference to the\nmajor movements of independent India. [6 Marks]",
        "answer": "Critical evaluation: Role of movements in Indian democracy; (1) Conscience of democracy: movements articulate\nthe grievances of the excluded, hold the state accountable, and expand the meaning of democracy beyond\nelectoral politics; (2) Examples: peasant and worker movements for land and wages, the Dalit movement for\ndignity and equality, the women's movement for rights and safety, environmental movements for ecological\njustice, and the RTI movement for transparency; (3) Achievements: legal reforms, policy changes, constitutional\nsafeguards, and the empowerment of marginalised groups; (4) Limitations: fragmentation, co-optation, violence,\nweak organisation, and uneven impact; (5) Conclusion: movements remain indispensable for deepening\ndemocracy and social justice.\nStep-by-Step Marking Scheme (1.5 Movements as conscience + 1.5 Marks examples + 1.5 Marks achievements + 1.5 Marks\nlimitations & conclusion):\n• 1. Movements as the Conscience of Democracy [1.5 Marks]:\n- Movements articulate the grievances of the excluded, hold the state accountable, and expand democracy beyond\nelectoral politics to substantive justice.\n• 2. Examples [1.5 Marks]:\n\n- Peasant and worker movements, the Dalit movement, the women's movement, environmental movements such as\nChipko and the Narmada Bachao Andolan, and the RTI movement.\n• 3. Achievements [1.5 Marks]:\n- Legal reforms, policy changes, constitutional safeguards, and the political and social empowerment of marginalised\ngroups.\n• 4. Limitations and Conclusion [1.5 Marks]:\n- Fragmentation, co-optation, violence, and uneven impact limit movements; nonetheless, they remain indispensable for\ndeepening democracy, protecting rights, and pursuing social justice.",
